        printf("%02x", salt[i]);
    }
    printf("\n");

    char password[] = "password";
    unsigned char hash_value[HASH_DIGEST_LENGTH];
    hash_password(password, salt, 1000, hash_value);
    printf("Hashed password: ");
    for (i = 0; i < HASH_DIGEST_LENGTH; i++) {
        printf("%02x", hash_value[i]);
    }
    printf("\n");

    return 0;
}

