#define MAX_FILE_NAME_LENGTH 256
#define MAX_BUFFER_SIZE 1024

// Function to read a file and print its contents
void read_file(const char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return;
    }

    char buffer[MAX_BUFFER_SIZE];
    size_t bytes_read = read(fd, buffer, MAX_BUFFER_SIZE);
    if (bytes_read == -1) {
        perror("Error reading from file");
        close(fd);
        return;
    }

    buffer[bytes_read] = '\0';
    printf("File contents: %s\n", buffer);

    close(fd);
}

// Function to write a file and print its contents
void write_file(const char *filename) {
    int fd = open(filename, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        perror("Error creating file");
        return;
    }

    char buffer[MAX_BUFFER_SIZE];
    gets(buffer); // Read input from user

    size_t bytes_written = write(fd, buffer, strlen(buffer));
    if (bytes_written == -1) {
        perror("Error writing to file");
        close(fd);
        return;
    }

    printf("File contents written: %s\n", buffer);

    close(fd);
}

int main() {
    // Example usage of read_file and write_file functions
    char filename[MAX_FILE_NAME_LENGTH];

    // Read a file and print its contents
    read_file("example.txt");

    // Create a new file and write some contents to it
    write_file("new_file.txt");

    // Read the contents of the new file and print them
    read_file("new_file.txt");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ITEMS 100

// Struct to hold item details
typedef struct {
    char name[50];
    float price;
    int quantity;
} item;

// Function to compare item prices
int comparePrices(const void *a, const void *b) {
    item *ia = (item *)a;
    item *ib = (item *)b;
    if (ia->price < ib->price)
        return -1;
    else if (ia->price > ib->price)
        return 1;
    else
        return 0;
}

// Function to print item details
void printItem(item i) {
    printf("Name: %s\n", i.name);
    printf("Price: $%.2f\n", i.price);
    printf("Quantity: %d\n", i.quantity);
    printf("\n");
}

// Function to calculate total cost of items
float calculateTotalCost(item *items, int numItems) {
    float totalCost = 0;
    for (int i = 0; i < numItems; i++) {
        totalCost += items[i].price * items[i].quantity;
    }
    return totalCost;
}

int main() {
    int numItems;
    printf("Enter the number of items: ");
    scanf("%d", &numItems);

    item *items = (item *)malloc(numItems * sizeof(item));

    for (int i = 0; i < numItems; i++) {
        printf("Enter item details for item %d:\n", i+1);
        printf("Name: ");
        scanf("%s", items[i].name);
        printf("Price: ");
        scanf("%f", &items[i].price);
        printf("Quantity: ");
        scanf("%d", &items[i].quantity);
    }

    // Sort items by price
    qsort(items, numItems, sizeof(item), comparePrices);

    // Print item details
    printf("Item details:\n");
    for (int i = 0; i < numItems; i++) {
        printItem(items[i]);
    }

    // Calculate total cost of items
    float totalCost = calculateTotalCost(items, numItems);
    printf("\nTotal cost: $%.2f\n", totalCost);

    free(items);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

void printPattern(int n, int i) {
    if (i > n) return; // Base case
    for (int j = 1; j <= i; j++) {
        printf("*"); // Print stars
    }
    printf("\n");
    printPattern(n, i + 1); // Recursive call
}

void reversePattern(int n, int i) {
    if (i < 1) return; // Base case
    for (int j = 1; j <= i; j++) {
        printf("*"); // Print stars
    }
    printf("\n");
    reversePattern(n, i - 1); // Recursive call
}

void printNumbers(int n, int i) {
    if (i > n) return; // Base case
    printf("%d ", i); // Print numbers
    printNumbers(n, i + 1); // Recursive call
}

void reverseNumbers(int n, int i) {
    if (i < 1) return; // Base case
    printf("%d ", i); // Print numbers
    reverseNumbers(n, i - 1); // Recursive call
}

void fibonacci(int a, int b, int n) {
    if (n <= 0) return; // Base case
    printf("%d ", a); // Print Fibonacci number
    fibonacci(b, a + b, n - 1); // Recursive call
}

void countdown(int n) {
    if (n < 1) {
        printf("Lift off!\n"); // Base case
        return;
    }
    printf("%d...\n", n); // Print countdown
    countdown(n - 1); // Recursive call
}

int power(int base, int exp) {
    if (exp == 0) return 1; // Base case
    return base * power(base, exp - 1); // Recursive definition
}

int factorial(int n) {
    if (n <= 1) return 1; // Base case
    return n * factorial(n - 1); // Recursive definition
}

int main() {
    int choice, n;

    printf("Welcome to the recursive functions program!\n");
    printf("Choose an option:\n");
    printf("1. Print Pattern\n");
    printf("2. Reverse Pattern\n");
    printf("3. Print Numbers\n");
    printf("4. Reverse Numbers\n");
    printf("5. Fibonacci Sequence\n");
    printf("6. Countdown\n");
    printf("7. Power\n");
    printf("8. Factorial\n");

    while (1) {
        printf("Enter your choice (1-8, or 0 to exit): ");
        scanf("%d", &choice);
        if (choice == 0) break;

        switch (choice) {
            case 1:
                printf("Enter the height of the pattern: ");
                scanf("%d", &n);
                printPattern(n, 1); 
                break;
            case 2:
                printf("Enter the height of the reverse pattern: ");
                scanf("%d", &n);
                reversePattern(n, n); 
                break;
            case 3:
                printf("Enter the number of integers to print: ");
                scanf("%d", &n);
                printNumbers(n, 1); 
                break;
            case 4:
                printf("Enter the number of integers to reverse print: ");
                scanf("%d", &n);
                reverseNumbers(n, n);
                break;
            case 5:
                printf("Enter the number of Fibonacci numbers to generate: ");
                scanf("%d", &n);
                printf("Fibonacci Series: ");
                fibonacci(0, 1, n);
                printf("\n");
                break;
            case 6:
                printf("Enter a number for countdown: ");
                scanf("%d", &n);
                countdown(n);
                break;
            case 7:
                printf("Enter base and exponent: ");
                int base, exp;
                scanf("%d %d", &base, &exp);
                printf("%d raised to the power of %d is %d\n", base, exp, power(base, exp));
                break;
            case 8:
                printf("Enter a number to compute factorial: ");
                scanf("%d", &n);
                printf("Factorial of %d is %d\n", n, factorial(n));
                break;
            default:
                printf("Invalid choice, please try again.\n");
        }
    }

    printf("Thank you for using the recursive functions program!\n");
    return 0;
}

