// Function to read CPU statistics from /proc/stat
void read_cpu_stats(long *user, long *nice, long *system, long *idle, long *iowait, long *irq, long *softirq) {
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
