#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define MAX_WIDTH 100
#define MAX_HEIGHT 100

// ASCII characters for different shades of gray
char *ascii_chars[] = {" ", ".", ":", "-", "=", "+", "*", "#", "%", "@"};

// Convert RGB values to grayscale
int get_grayscale(uint8_t r, uint8_t g, uint8_t b) {
    return (r * 0.2126 + g * 0.7152 + b * 0.0722);
}

int main(int argc, char **argv) {
    // Open image file
    FILE *infile = fopen(argv[1], "rb");
    if (!infile) {
        fprintf(stderr, "Error opening file: %s\n", argv[1]);
        return 1;
    }

    // Read image header
    char magic[2];
    int width, height, maxval;
    fscanf(infile, "%2s\n%d %d\n%d\n", magic, &width, &height, &maxval);

    // Check if image is valid
    if (magic[0] != 'P' || magic[1] != '6') {
        fprintf(stderr, "Invalid image format: %s\n", argv[1]);
        fclose(infile);
        return 1;
    }

    // Allocate memory for image data
    uint8_t *data = (uint8_t *)malloc(width * height * 3 * sizeof(uint8_t));
    if (!data) {
        fprintf(stderr, "Error allocating memory\n");
        fclose(infile);
        return 1;
    }

    // Read image data
    fread(data, sizeof(uint8_t), width * height * 3, infile);

    // Close image file
    fclose(infile);

    // Convert image to ASCII art
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            // Compute grayscale value
            int gray = get_grayscale(data[(y * width + x) * 3],
                                      data[(y * width + x) * 3 + 1],
                                      data[(y * width + x) * 3 + 2]);

            // Map grayscale value to ASCII character
            int index = gray * 10 / 255;
            printf("%s", ascii_chars[index]);
        }
        printf("\n");
    }

    // Free memory
    free(data);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY_SIZE 10

typedef struct MemoryItem {
    char data[MAX_MEMORY_SIZE];
    struct MemoryItem* next;
} MemoryItem;

MemoryItem* CreateMemoryItem(char data) {
    MemoryItem* item = malloc(sizeof(MemoryItem));
    item->data[0] = data;
    item->next = NULL;
    return item;
}

void AddToMemory(MemoryItem* head, char data) {
    MemoryItem* item = CreateMemoryItem(data);
    if (head == NULL) {
        head = item;
    } else {
        head->next = item;
        head = item;
    }
}

int PlayMemoryGame() {
    // Seed the random number generator
    srand(time(NULL));

    // Create a linked list of memory items
    MemoryItem* head = NULL;

    // Add some memory items to the list
    AddToMemory(head, 'a');
    AddToMemory(head, 'b');
    AddToMemory(head, 'c');
    AddToMemory(head, 'd');
    AddToMemory(head, 'e');

    // Play the game
    int guess_count = 0;
    char guess;

    // Loop until the user guesses the right item or runs out of guesses
    while (guess_count < 5) {
        // Get the user's guess
        printf("Enter your guess: ");
        scanf("%c", &guess);

        // Check if the guess is correct
        if (guess == head->data) {
            // The guess is correct
            printf("Congratulations! You won!\n");
            break;
        } else if (guess < head->data) {
            // The guess is too low
            printf("Your guess is too low. Try again.\n");
        } else {
            // The guess is too high
            printf("Your guess is too high. Try again.\n");
        }

        // Increment the guess count
        guess_count++;
    }

    // If the user runs out of guesses, they lose
    if (guess_count == 5) {
        printf("Sorry, you lose. The answer was %c.\n", head->data);
    }

    return 0;
}

int main() {
    PlayMemoryGame();
    return 0;
}

