            int asciiIndex = (int) round((double) grayValue / MAX_PIXEL * 9);
            if (asciiIndex > 9) {
                asciiIndex = 9;
            }
            asciiData[index / MAX_WIDTH][index % MAX_WIDTH] = " .:-=+*#%@@"[asciiIndex];
