void sha256_transform(const uint8_t *message, uint32_t *state) {
    uint32_t a, b, c, d, e, f, g, h, temp1, temp2, schedule[64];

    for (int i = 0; i < 16; i++) {
        schedule[i] = BIGENDIAN32(((uint32_t *)message)[i]);
