    }
    if(board[2][0]==player&&board[1][1]==player&&board[0][2]==player){
        return 1;
    }
    return 0;
}

int evaluate_board(char board[BOARD_SIZE][BOARD_SIZE],char ai,char human)
{
    int score = 0;
    if(check_winner(board,ai)){
        score = 1;
    } else if(check_winner(board,human)){
        score = -1;
    }
    return score;
}

int minimax(char board[BOARD_SIZE][BOARD_SIZE],int depth,int alpha,int beta,int is_maximizing_player,char ai,char human)
{
    int score;
    if(check_winner(board,ai)){
        return 1;
    }
    if(check_winner(board,human)){
        return -1;
    }
    if(depth==0){
        return 0;
    }

    if(is_maximizing_player){
        int max_score = -9999;
        for(int i=0;i<BOARD_SIZE;i++){
            for(int j=0;j<BOARD_SIZE;j++){
                if(board[i][j]==' '){
                    board[i][j] = ai;
                    score = minimax(board,depth-1,alpha,beta,0,ai,human);
                    board[i][j] = ' ';
                    if(score > max_score){
                        max_score = score;
                    }
                    if(max_score > alpha){
                        alpha = max_score;
                    }
                    if(alpha >= beta){
                        return max_score;
                    }
                }
            }
        }
        return max_score;
    } else {
        int min_score = 9999;
        for(int i=0;i<BOARD_SIZE;i++){
            for(int j=0;j<BOARD_SIZE;j++){
                if(board[i][j]==' '){
                    board[i][j] = human;
                    score = minimax(board,depth-1,alpha,beta,1,ai,human);
                    board[i][j] = ' ';
                    if(score < min_score){
                        min_score = score;
                    }
                    if(min_score < beta){
                        beta = min_score;
                    }
                    if(beta <= alpha){
                        return min_score;
                    }
                }
            }
        }
        return min_score;
    }
}

