// Define the conversion function
double convert_units(double value, char from_unit, char to_unit)
{
    switch (from_unit)
    {
        case 'm':
            switch (to_unit)
            {
                case 'kg':
                    return value * 1000;
                case 'g':
                    return value * 1000000;
                case 't':
                    return value * 1000000000;
            }
            break;
        case 'kg':
            switch (to_unit)
            {
                case 'm':
                    return value * 0.001;
                case 'g':
                    return value * 1000;
                case 't':
                    return value * 1000000;
            }
            break;
        case 'g':
            switch (to_unit)
            {
                case 'm':
                    return value * 0.000001;
                case 'kg':
                    return value * 0.001;
                case 't':
                    return value * 1000000;
            }
            break;
        case 't':
            switch (to_unit)
            {
                case 'm':
                    return value * 0.0000001;
                case 'kg':
                    return value * 0.000001;
                case 'g':
                    return value * 0.001;
            }
            break;
    }

    return -1;
}

int main()
{
