    double converted_value = convert_units(value, from_unit, to_unit);

    if (converted_value != -1)
    {
        printf("The converted value is: %.2lf %s", converted_value, to_unit);
    }
    else
    {
        printf("Error converting units");
    }

    return 0;
}

