void enqueue(struct queue* q, int num) {
    if(is_full(q)) {
        printf("Queue is Full!\n");
        return;
    }
    if(is_empty(q)) {
        q->front = 0;
        q->rear=0;
    }
    else {
        q->rear += 1;
    }
    q->arr[q->rear] = num;
    q->size += 1;
}

