void
process_bitmap_updates(STREAM s)
{
	int i;
	uint16 num_updates;

	in_uint16_le(s, num_updates);   /* rectangles */

	for (i = 0; i < num_updates; i++)
	{
		process_bitmap_data(s);
 	}
