#define MAX_URL_LENGTH 2048

typedef struct {
    char *url;
    char *scheme;
    char *host;
    char *path;
    char *query;
    char *fragment;
} URLParts;

URLParts *sanitize_url(const char *url) {
    URLParts *parts = malloc(sizeof(URLParts));
    if (parts == NULL) {
        printf("Error: Failed to allocate memory for URLParts.\n");
        exit(1);
    }

    char *scheme_end = strstr(url, "://");
    if (scheme_end == NULL) {
        printf("Error: Invalid URL format.\n");
        free(parts);
        exit(1);
    }

    parts->url = strndup(url, MAX_URL_LENGTH);
    parts->scheme = strndup(url, scheme_end - url);
    parts->host = strndup(scheme_end + 3, strcspn(scheme_end + 3, "/?#"));
    parts->path = strndup(strchr(scheme_end + 3, '/'), strlen(scheme_end + 3) - strcspn(scheme_end + 3, "/?#"));
    parts->query = strndup(strchr(parts->path, '?'), strlen(parts->path) - strcspn(parts->path, "?#"));
    parts->fragment = strndup(strchr(parts->path, '#'), strlen(parts->path) - strcspn(parts->path, "?#"));

    return parts;
}

void print_url_parts(const URLParts *parts) {
    printf("URL: %s\n", parts->url);
    printf("Scheme: %s\n", parts->scheme);
    printf("Host: %s\n", parts->host);
    printf("Path: %s\n", parts->path);
    printf("Query: %s\n", parts->query);
    printf("Fragment: %s\n", parts->fragment);
}

void free_url_parts(URLParts *parts) {
    free(parts->url);
    free(parts->scheme);
    free(parts->host);
    free(parts->path);
    free(parts->query);
    free(parts->fragment);
    free(parts);
}

int main() {
    char input[MAX_URL_LENGTH];
    printf("Enter a URL to sanitize: ");
    fgets(input, MAX_URL_LENGTH, stdin);

    URLParts *parts = sanitize_url(input);
    if (parts == NULL) {
        return 1;
    }

    print_url_parts(parts);

    free_url_parts(parts);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <unistd.h>

typedef struct {
    char *host;
    char *port;
    char *path;
    char *query;
} HTTP_Request;

typedef struct {
    int code;
    char *message;
    char *headers;
    char *body;
} HTTP_Response;

HTTP_Request *HTTP_Request_new(char *host, char *port, char *path, char *query) {
    HTTP_Request *request = malloc(sizeof(HTTP_Request));
    request->host = malloc(strlen(host) + 1);
    request->port = malloc(strlen(port) + 1);
    request->path = malloc(strlen(path) + 1);
    request->query = malloc(strlen(query) + 1);
    strcpy(request->host, host);
    strcpy(request->port, port);
    strcpy(request->path, path);
    strcpy(request->query, query);
    return request;
}

void HTTP_Request_free(HTTP_Request *request) {
    free(request->host);
    free(request->port);
    free(request->path);
    free(request->query);
    free(request);
}

HTTP_Response *HTTP_Request_send(HTTP_Request *request) {
    int sockfd, n;
    struct sockaddr_in serv_addr;
    struct hostent *server;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error opening socket");
        return NULL;
    }

    server = gethostbyname(request->host);
    if (server == NULL) {
        perror("Error getting host by name");
        return NULL;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(atoi(request->port));
    memcpy(&serv_addr.sin_addr.s_addr, server->h_addr, server->h_length);

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Error connecting to server");
        return NULL;
    }

    char *request_string = malloc(strlen("GET ") + strlen(request->path) + strlen(" HTTP/1.1\r\nHost: ") + strlen(request->host) + strlen("\r\n\r\n") + 1);
    sprintf(request_string, "GET %s HTTP/1.1\r\nHost: %s\r\n\r\n", request->path, request->host);

    n = write(sockfd, request_string, strlen(request_string));
    if (n < 0) {
        perror("Error writing to socket");
        return NULL;
    }

    char *response = malloc(4096);
    n = read(sockfd, response, 4096);
    if (n < 0) {
        perror("Error reading from socket");
        return NULL;
    }

    HTTP_Response *response_struct = malloc(sizeof(HTTP_Response));
    response_struct->code = atoi(strtok(response, " "));
    response_struct->message = strtok(NULL, "\r\n");
    response_struct->headers = strtok(NULL, "\r\n\r\n");
    response_struct->body = strtok(NULL, "\0");

    free(request_string);
    free(response);
    close(sockfd);
    return response_struct;
}

void HTTP_Response_free(HTTP_Response *response) {
    free(response->message);
    free(response->headers);
    free(response->body);
    free(response);
}

int main() {
    HTTP_Request *request = HTTP_Request_new("example.com", "80", "/", "foo=bar");
    HTTP_Response *response = HTTP_Request_send(request);
    printf("Code: %d\n", response->code);
    printf("Message: %s\n", response->message);
    printf("Headers: %s\n", response->headers);
    printf("Body: %s\n", response->body);
    HTTP_Response_free(response);
    HTTP_Request_free(request);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/stat.h>

#define BUFFER_SIZE 256
#define INTERVAL 1

// Function to read CPU statistics from /proc/stat
void read_cpu_stats(long *user, long *nice, long *system, long *idle, long *iowait, long *irq, long *softirq) {
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Failed to open /proc/stat");
        exit(EXIT_FAILURE);
    }

    char buffer[BUFFER_SIZE];
    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        sscanf(buffer, "cpu %ld %ld %ld %ld %ld %ld %ld", user, nice, system, idle, iowait, irq, softirq);
    }

    fclose(fp);
}

// Function to calculate CPU usage
double calculate_cpu_usage(long prev_total, long prev_idle, long total, long idle) {
    long total_diff = total - prev_total;
    long idle_diff = idle - prev_idle;
    return (total_diff - idle_diff) * 100.0 / total_diff; // return usage percentage
}

// Main function
int main() {
    long user, nice, system, idle, iowait, irq, softirq;
    long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq;

    // Initial read of CPU stats
    read_cpu_stats(&prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq);
    long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq;

    while (1) {
        sleep(INTERVAL); // wait for specified interval

        // Read current CPU stats
        read_cpu_stats(&user, &nice, &system, &idle, &iowait, &irq, &softirq);
        long total = user + nice + system + idle + iowait + irq + softirq;

        // Calculate CPU usage
        double cpu_usage = calculate_cpu_usage(prev_total, prev_idle, total, idle);

        // Print CPU usage
        printf("CPU Usage: %.2f%%\n", cpu_usage);

        // Update previous stats
        prev_user = user;
        prev_nice = nice;
        prev_system = system;
        prev_idle = idle;
        prev_iowait = iowait;
        prev_irq = irq;
        prev_softirq = softirq;
        prev_total = total;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    char *binary;
    int decimal;
} binary_t;

binary_t *binary_table = NULL;
int table_size = 0;

void init_binary_table() {
    binary_table = (binary_t *) malloc(sizeof(binary_t));
    table_size = 1;
    strcpy(binary_table[0].binary, "0");
    binary_table[0].decimal = 0;
}

void add_binary_entry(char *binary, int decimal) {
    binary_t *new_table = (binary_t *) realloc(binary_table, sizeof(binary_t) * (table_size + 1));
    if (new_table == NULL) {
        printf("Error: Memory allocation failed.\n");
        exit(1);
    }
    binary_table = new_table;
    strcpy(binary_table[table_size].binary, binary);
    binary_table[table_size].decimal = decimal;
    table_size++;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <decimal_number>\n", argv[0]);
        exit(1);
    }

    int decimal = atoi(argv[1]);

    if (decimal < 0 || decimal > 255) {
        printf("Error: Input must be between 0 and 255.\n");
        exit(1);
    }

    init_binary_table();
    add_binary_entry("0", 0);
    add_binary_entry("1", 1);

    char binary[9];
    int i = 0;
    while (decimal > 0) {
        binary[i++] = '0' + decimal % 2;
        decimal /= 2;
    }

    printf("Decimal: %d\n", decimal);
    printf("Binary:  ");
    for (int j = i - 1; j >= 0; j--) {
        printf("%c", binary[j]);
    }
    printf("\n");

    return 0;
}

