#define KEY 3

void encrypt(char *message) {
    int i, j, k;
    char c, d;
    int freq[26];

    // Frequency Analysis Attack
    for (i = 0; i < 26; i++) {
        freq[i] = 0;
    }
    for (i = 0; i < strlen(message); i++) {
        freq[message[i] - 'a']++;
    }

    // Caesar Cipher Encryption
    for (i = 0; i < strlen(message); i++) {
        c = message[i];
        d = (c + KEY) % 26;
        message[i] = d + 'a';
    }
}

void decrypt(char *message) {
    int i, j, k;
    char c, d;
    int freq[26];

    // Frequency Analysis Attack
    for (i = 0; i < 26; i++) {
        freq[i] = 0;
    }
    for (i = 0; i < strlen(message); i++) {
        freq[message[i] - 'a']++;
    }

    // Caesar Cipher Decryption
    for (i = 0; i < strlen(message); i++) {
        c = message[i];
        d = (c - KEY) % 26;
        message[i] = d + 'a';
    }
}

int main() {
    char message[] = "Hello World!";
    encrypt(message);
    printf("Encrypted Message: %s\n", message);
    decrypt(message);
    printf("Decrypted Message: %s\n", message);
    return 0;
}

