#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <arpa/inet.h>

#define SERVER_PORT 8080
#define BUFFER_SIZE 1024
#define TEST_DURATION 5

void error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void speedTest(int sockfd) {
    char buffer[BUFFER_SIZE];
    size_t totalBytesSent = 0;
    size_t totalBytesReceived = 0;
    time_t startTime, endTime;

    // Start the timer
    time(&startTime);
    while (1) {
        // Send data
        ssize_t bytesSent = send(sockfd, buffer, BUFFER_SIZE, 0);
        if (bytesSent < 0) {
            error("Error sending data");
        }
        totalBytesSent += bytesSent;

        // Receive data
        ssize_t bytesReceived = recv(sockfd, buffer, BUFFER_SIZE, 0);
        if (bytesReceived < 0) {
            error("Error receiving data");
        }
        totalBytesReceived += bytesReceived;

        // Check elapsed time
        time(&endTime);
        if (difftime(endTime, startTime) >= TEST_DURATION) {
            break;
        }
    }

    double elapsedTime = difftime(endTime, startTime);

    // Calculate speeds
    double uploadSpeed = (totalBytesSent * 8) / (elapsedTime * 1000000); // Mbps
    double downloadSpeed = (totalBytesReceived * 8) / (elapsedTime * 1000000); // Mbps

    printf("Upload Speed: %.2f Mbps\n", uploadSpeed);
    printf("Download Speed: %.2f Mbps\n", downloadSpeed);
}

int main() {
    int sockfd;
    struct sockaddr_in serverAddr;

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        error("Error opening socket");
    }

    // Configure server address
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(SERVER_PORT);
    serverAddr.sin_addr.s_addr = inet_addr("127.0.0.1"); // Localhost for testing

    // Connect to the server
    if (connect(sockfd, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) < 0) {
        error("Error connecting to server");
    }

    printf("Connected to the server. Starting speed test...\n");

    // Run speed test
    speedTest(sockfd);

    // Close the socket
    close(sockfd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Struct to store contact information
struct Contact {
    char name[50];
    char phone_number[20];
    char email[100];
};

// Function to add contact to the phone book
void add_contact(struct Contact *contacts, int num_contacts) {
    char input[100];
    printf("Enter name: ");
    fgets(input, 100, stdin);
    strcpy(contacts[num_contacts].name, input);
    contacts[num_contacts].name[strcspn(contacts[num_contacts].name, "\n")] = 0; // remove newline

    printf("Enter phone number: ");
    fgets(input, 100, stdin);
    strcpy(contacts[num_contacts].phone_number, input);
    contacts[num_contacts].phone_number[strcspn(contacts[num_contacts].phone_number, "\n")] = 0; // remove newline

    printf("Enter email: ");
    fgets(input, 100, stdin);
    strcpy(contacts[num_contacts].email, input);
    contacts[num_contacts].email[strcspn(contacts[num_contacts].email, "\n")] = 0; // remove newline

    printf("Contact added successfully!\n");
}

// Function to search for a contact by name
void search_contact(struct Contact *contacts, int num_contacts) {
    char search_name[50];
    printf("Enter name to search for: ");
    fgets(search_name, 50, stdin);
    search_name[strcspn(search_name, "\n")] = 0; // remove newline

    int found = 0;
    for (int i = 0; i < num_contacts; i++) {
        if (strcmp(contacts[i].name, search_name) == 0) {
            printf("Name: %s\n", contacts[i].name);
            printf("Phone Number: %s\n", contacts[i].phone_number);
            printf("Email: %s\n", contacts[i].email);
            found = 1;
            break;
        }
    }
    if (!found) {
        printf("Contact not found.\n");
    }
}

int main() {
    int num_contacts = 0;
    struct Contact *contacts = malloc(sizeof(struct Contact));

    printf("Welcome to the Phone Book!\n\n");

    while (1) {
        printf("Menu:\n");
        printf("1. Add Contact\n");
        printf("2. Search Contact\n");
        printf("3. Quit\n\n");

        char input[100];
        printf("Enter choice: ");
        fgets(input, 100, stdin);

        if (strcmp(input, "1\n") == 0) {
            add_contact(contacts, num_contacts);
            num_contacts++;
            contacts = realloc(contacts, (num_contacts + 1) * sizeof(struct Contact)); // resize array
        }
        else if (strcmp(input, "2\n") == 0) {
            search_contact(contacts, num_contacts);
        }
        else if (strcmp(input, "3\n") == 0) {
            break;
        }
        else {
            printf("Invalid choice. Please try again.\n");
        }

        printf("\n");
    }

    free(contacts);

    return 0;
}

#include <stdio.h>

void menu()
{
    printf("\n--- UNIT CONVERTER ---\n");
    printf("1. Feet to meters\n");
    printf("2. Miles to kilometers\n");
    printf("3. Pounds to kilograms\n");
    printf("4. Gallons to liters\n");
    printf("5. Fahrenheit to Celsius\n");
    printf("6. Exit\n");
    printf("Enter your choice: ");
}

void feet_to_meters()
{
    float feet, meters;
    printf("Enter measurement in feet: ");
    scanf("%f", &feet);
    meters = feet * 0.3048;
    printf("%.2f feet = %.2f meters\n", feet, meters);
}

void miles_to_kilometers()
{
    float miles, kilometers;
    printf("Enter measurement in miles: ");
    scanf("%f", &miles);
    kilometers = miles * 1.60934;
    printf("%.2f miles = %.2f kilometers\n", miles, kilometers);
}

void pounds_to_kilograms()
{
    float pounds, kilograms;
    printf("Enter weight in pounds: ");
    scanf("%f", &pounds);
    kilograms = pounds * 0.453592;
    printf("%.2f pounds = %.2f kilograms\n", pounds, kilograms);
}

void gallons_to_liters()
{
    float gallons, liters;
    printf("Enter volume in gallons: ");
    scanf("%f", &gallons);
    liters = gallons * 3.78541;
    printf("%.2f gallons = %.2f liters\n", gallons, liters);
}

void fahrenheit_to_celsius()
{
    float fahrenheit, celsius;
    printf("Enter temperature in Fahrenheit: ");
    scanf("%f", &fahrenheit);
    celsius = (fahrenheit - 32) * 5 / 9;
    printf("%.2f degrees Fahrenheit = %.2f degrees Celsius\n", fahrenheit, celsius);
}

int main()
{
    int choice;
    do
    {
        menu();
        scanf("%d", &choice);
        switch (choice)
        {
            case 1:
                feet_to_meters();
                break;
            case 2:
                miles_to_kilometers();
                break;
            case 3:
                pounds_to_kilograms();
                break;
            case 4:
                gallons_to_liters();
                break;
            case 5:
                fahrenheit_to_celsius();
                break;
            case 6:
                printf("Goodbye!\n");
                break;
            default:
                printf("Invalid choice!\n");
        }
    } while (choice != 6);
    return 0;
}

