            if (choice == 'a' || choice == 'A')
                allow = true;
            else if (choice == 'b' || choice == 'B')
                allow = false;
            else {
                printf("Invalid choice!\n");
                continue;
            }
            add_rule(ip_address, allow);
        } else if (choice == 'n' || choice == 'N') {
