      printf("Out of memory.\n");
    } else {
      // Otherwise, print a generic error message.
      perror("malloc");
      exit(EXIT_FAILURE);
    }
  // Free the memory.
  } else {
    free(buffer);
  }

  // Read from the file.
  size_t bytes_read = fread(buffer, 1, 1024, file);
  if (bytes_read == 0) {
    // Check if the end of file was reached.
    if (feof(file)) {
      printf("End of file reached.\n");
    } else {
      // Otherwise, print a generic error message.
      perror("fread");
      exit(EXIT_FAILURE);
