#include<stdio.h>
#include<stdlib.h>
#include<string.h>

// Huffman tree node
struct Node {
    int frequency;
    char character;
    struct Node* left;
    struct Node* right;
};

// Utility function to create a new huffman tree node
struct Node* create_node(char character, int frequency, struct Node* left, struct Node* right) {
    struct Node* temp = (struct Node*)malloc(sizeof(struct Node));
    temp->character = character;
    temp->frequency = frequency;
    temp->left = left;
    temp->right = right;
    return temp;
}

// Utility function to read the frequency table from file and create the huffman tree
struct Node* create_huffman_tree_from_file(char* filename) {
    FILE* fp;
    if ((fp = fopen(filename, "r")) == NULL) {
        printf("Error opening file! \n");
        exit(1);
    }
    char c;
    int f;
    struct Node* nodes[256];
    for (int i = 0; i < 256; i++) {
        fscanf(fp, "%c %d\n", &c, &f);
        nodes[i] = create_node(c, f, NULL, NULL);
    }
    fclose(fp);
    int num_nodes = 256;

    while (num_nodes > 1) {
        int min1 = 0, min2 = 1;
        if (nodes[min2]->frequency < nodes[min1]->frequency) {
            int temp = min1;
            min1 = min2;
            min2 = temp;
        }
        for (int i = 2; i < num_nodes; i++) {
            if (nodes[i]->frequency < nodes[min1]->frequency) {
                min2 = min1;
                min1 = i;
            } else if (nodes[i]->frequency < nodes[min2]->frequency) {
                min2 = i;
            }
        }

        struct Node* new_node = create_node('*', nodes[min1]->frequency + nodes[min2]->frequency, nodes[min1], nodes[min2]);

        nodes[min1] = new_node;

        for (int i = min2; i < num_nodes - 1; i++) {
            nodes[i] = nodes[i+1];
        }
        num_nodes--;

        // Update min2 in case it was referring to the node just deleted
        if (min1 == num_nodes) {
            int temp = min1;
            min1 = min2;
            min2 = temp;
        }
        for (int i = min2; i < num_nodes - 1; i++) {
            if (nodes[i]->frequency < nodes[min1]->frequency) {
                min2 = min1;
                min1 = i;
            } else if (nodes[i]->frequency < nodes[min2]->frequency) {
                min2 = i;
            }
        }
    } 

    return nodes[0];
}

// Utility function to print the huffman code for all characters
void print_huffman_codes(struct Node* root, int arr[], int top) {
    if (root->left) {
        arr[top] = 0;
        print_huffman_codes(root->left, arr, top + 1);
    }
    if (root->right) {
        arr[top] = 1;
        print_huffman_codes(root->right, arr, top + 1);
    }

    if (!root->left && !root->right) {
        printf("%c: ", root->character);
        for (int i = 0; i < top; i++) {
            printf("%d", arr[i]);
        }
        printf("\n");
    }
}

int main() {
    char* filename = "frequency_table.txt";
    struct Node* root = create_huffman_tree_from_file(filename);
    int arr[100], top = 0;
    print_huffman_codes(root, arr, top);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PIXEL 255

#define RED 0
#define GREEN 1
#define BLUE 2

typedef struct Pixel {
    unsigned char r;     // red component
    unsigned char g;     // green component
    unsigned char b;     // blue component
} Pixel;

typedef struct Image {
    int width;           // width of image
    int height;          // height of image
    Pixel *data;         // array of pixels
} Image;

// allocate memory for an image of the given width and height
Image *create_image(int width, int height) {
    Image *image = (Image*) malloc(sizeof(Image));
    image->width = width;
    image->height = height;
    image->data = (Pixel*) malloc(width * height * sizeof(Pixel));
    return image;
}

// free memory allocated for an image
void delete_image(Image *image) {
    free(image->data);
    free(image);
}

// read image data from a file
Image *read_image(const char *filename) {
    // open file for reading
    FILE *file = fopen(filename, "r");

    // check if file was opened successfully
    if (file == NULL) {
        printf("Error: could not open file '%s'\n", filename);
        return NULL;
    }

    // read image dimensions from file
    int width, height;
    fscanf(file, "%d %d", &width, &height);

    // create image object
    Image *image = create_image(width, height);

    // read pixel data from file
    for (int i = 0; i < width * height; i++) {
        fscanf(file, "%hhu %hhu %hhu", &image->data[i].r, &image->data[i].g, &image->data[i].b);
    }

    // close file
    fclose(file);

    return image;
}

// write image data to a file
void write_image(const char *filename, Image *image) {
    // open file for writing
    FILE *file = fopen(filename, "w");

    // write image dimensions to file
    fprintf(file, "%d %d\n", image->width, image->height);

    // write pixel data to file
    for (int i = 0; i < image->width * image->height; i++) {
        fprintf(file, "%hhu %hhu %hhu\n", image->data[i].r, image->data[i].g, image->data[i].b);
    }

    // close file
    fclose(file);
}

// flip image vertically
void flip_vertical(Image *image) {
    int half_height = image->height / 2;
    for (int y = 0; y < half_height; y++) {
        for (int x = 0; x < image->width; x++) {
            Pixel temp = image->data[y * image->width + x];
            image->data[y * image->width + x] = image->data[(image->height - 1 - y) * image->width + x];
            image->data[(image->height - 1 - y) * image->width + x] = temp;
        }
    }
}

// apply grayscale filter to image
void grayscale_filter(Image *image) {
    for (int i = 0; i < image->width * image->height; i++) {
        unsigned char gray = (image->data[i].r + image->data[i].g + image->data[i].b) / 3;
        image->data[i].r = gray;
        image->data[i].g = gray;
        image->data[i].b = gray;
    }
}

// apply red filter to image
void red_filter(Image *image) {
    for (int i = 0; i < image->width * image->height; i++) {
        image->data[i].g = 0;
        image->data[i].b = 0;
    }
}

int main() {
    // read image from file
    Image *image = read_image("input.ppm");

    // apply filters
    flip_vertical(image);
    grayscale_filter(image);
    red_filter(image);

    // write image to file
    write_image("output.ppm", image);

    // free memory allocated for image
    delete_image(image);

    // return success
    return 0;
}

