// function to calculate number of days in a month
int daysInMonth(int month, int year){

    int numDays;

    switch (month){
        case 1:
            numDays = 31;
            break;
        case 2:
            if(((year%100 == 0) && (year%400 == 0)) || ((year%100 != 0) && (year%4 == 0))){
                numDays = 29;
            }
            else{
                numDays = 28;
            }
            break;
        case 3:
            numDays = 31;
            break;
        case 4:
            numDays = 30;
            break;
        case 5:
            numDays = 31;
            break;
        case 6:
            numDays = 30;
            break;
        case 7:
            numDays = 31;
            break;
        case 8:
            numDays = 31;\
            break;
        case 9:
            numDays = 30;
            break;
        case 10:
            numDays = 31;
            break;
        case 11:
            numDays = 30;
            break;
        case 12:
            numDays = 31;
            break;
        default:
            printf("Invalid month input!\n");
            numDays = -1;
            break;
    }
    return numDays;
}

int main(){

    char inputDate[12];
    int month, day, year, daysInYear, daysInInputYear, dayCount;

    printf("Please enter date in format mm-dd-yyyy: ");
    fgets(inputDate, 12, stdin);
    inputDate[strcspn(inputDate, "\n")] = '\0'; // removing trailing newline character

    sscanf(inputDate, "%d-%d-%d", &month, &day, &year);

    // validating input
    if((month < 1) || (month > 12)){
        printf("Invalid month!\n");
        return 1;
    }
    if((day < 1) || (day > daysInMonth(month, year))){
        printf("Invalid day!\n");
        return 1;
    }
    if(year < 1){
        printf("Invalid year!\n");
        return 1;
    }

    // calculating number of days
    daysInYear = 365;
    daysInInputYear = daysInMonth(month, year) - day + 1;
    dayCount = daysInInputYear;
    month++;

    while(month <= 12){
        dayCount += daysInMonth(month, year);
        month++;
    }

    year++;
    while(year != 2022){
        if(year%4 == 0){
            daysInYear = 366;
        }
        else{
            daysInYear = 365;
        }
        dayCount += daysInYear;
        year++;
    }

    printf("The date %s is the %dth day of the year %d.\n", inputDate, dayCount, 2021);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_URL_LENGTH 2048

typedef struct {
    char *url;
    char *scheme;
    char *host;
    char *path;
    char *query;
    char *fragment;
} URLParts;

URLParts *sanitize_url(const char *url) {
    URLParts *parts = malloc(sizeof(URLParts));
    if (parts == NULL) {
        printf("Error: Failed to allocate memory for URLParts.\n");
        exit(1);
    }

    char *scheme_end = strstr(url, "://");
    if (scheme_end == NULL) {
        printf("Error: Invalid URL format.\n");
        free(parts);
        exit(1);
    }

    parts->url = strndup(url, MAX_URL_LENGTH);
    parts->scheme = strndup(url, scheme_end - url);
    parts->host = strndup(scheme_end + 3, strcspn(scheme_end + 3, "/?#"));
    parts->path = strndup(strchr(scheme_end + 3, '/'), strlen(scheme_end + 3) - strcspn(scheme_end + 3, "/?#"));
    parts->query = strndup(strchr(parts->path, '?'), strlen(parts->path) - strcspn(parts->path, "?#"));
    parts->fragment = strndup(strchr(parts->path, '#'), strlen(parts->path) - strcspn(parts->path, "?#"));

    return parts;
}

void print_url_parts(const URLParts *parts) {
    printf("URL: %s\n", parts->url);
    printf("Scheme: %s\n", parts->scheme);
    printf("Host: %s\n", parts->host);
    printf("Path: %s\n", parts->path);
    printf("Query: %s\n", parts->query);
    printf("Fragment: %s\n", parts->fragment);
}

void free_url_parts(URLParts *parts) {
    free(parts->url);
    free(parts->scheme);
    free(parts->host);
    free(parts->path);
    free(parts->query);
    free(parts->fragment);
    free(parts);
}

int main() {
    char input[MAX_URL_LENGTH];
    printf("Enter a URL to sanitize: ");
    fgets(input, MAX_URL_LENGTH, stdin);

    URLParts *parts = sanitize_url(input);
    if (parts == NULL) {
        return 1;
    }

    print_url_parts(parts);

    free_url_parts(parts);
    return 0;
}

