#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the sentiment scores for each word
int sentiment_scores[] = {
    [0] = 0,  // "not"
    [1] = -1, // "bad"
    [2] = 1,  // "good"
    [3] = -2, // "terrible"
    [4] = 2,  // "excellent"
};

// Get the sentiment score for a given word
int get_sentiment_score(char *word) {
    for (int i = 0; i < sizeof(sentiment_scores) / sizeof(int); i++) {
        if (strcmp(word, sentiment_scores[i]) == 0) {
            return sentiment_scores[i];
        }
    }

    return 0;  // Return 0 for words not found in the sentiment dictionary
}

// Analyze the sentiment of a given sentence
int analyze_sentiment(char *sentence) {
    // Tokenize the sentence into words
    char *words[100];
    int num_words = 0;
    char *token = strtok(sentence, " ");
    while (token != NULL) {
        words[num_words++] = token;
        token = strtok(NULL, " ");
    }

    // Calculate the total sentiment score
    int total_score = 0;
    for (int i = 0; i < num_words; i++) {
        total_score += get_sentiment_score(words[i]);
    }

    return total_score;
}

// Main function
int main() {
    // Get the input sentence from the user
    char sentence[100];
    printf("Enter a sentence: ");
    gets(sentence);

    // Analyze the sentiment of the sentence
    int sentiment_score = analyze_sentiment(sentence);

    // Print the sentiment score
    if (sentiment_score > 0) {
        printf("The sentence has a positive sentiment.\n");
    } else if (sentiment_score < 0) {
        printf("The sentence has a negative sentiment.\n");
    } else {
        printf("The sentence has a neutral sentiment.\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/socket.h>
#include <unistd.h>
#include <netdb.h>

#define SERVER_PORT 8080

int main()
{
    int sockfd, clientfd;
    struct sockaddr_in server_addr, client_addr;
    char buffer[1024];
    double download_speed, upload_speed;
    time_t start_time, end_time;
    long bytes_received, bytes_sent;

    // Create a socket
    sockfd = socket(AF_INET, SOCK_STREAM, htons(SERVER_PORT));

    // Connect to the server
    clientfd = connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr));

    // Start the timer
    start_time = time(NULL);

    // Send a file
    bytes_sent = send(clientfd, "Hello, world!", 13, 0);

    // Receive a file
    bytes_received = recv(clientfd, buffer, 1024, 0);

    // End the timer
    end_time = time(NULL);

    // Calculate the download speed
    download_speed = (bytes_received / (double)end_time - start_time) * 8;

    // Calculate the upload speed
    upload_speed = (bytes_sent / (double)end_time - start_time) * 8;

    // Print the results
    printf("Download speed: %.2f Mbps\n", download_speed);
    printf("Upload speed: %.2f Mbps\n", upload_speed);

    // Close the socket
    close(sockfd);

    return 0;
}

