#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_CLIENTS 10

typedef struct {
    int sockfd;
    struct sockaddr_in addr;
} client_t;

typedef struct {
    int num_clients;
    client_t clients[MAX_CLIENTS];
} proxy_t;

proxy_t proxy;

void *handle_client(void *arg) {
    client_t *client = (client_t *)arg;
    char buffer[1024];
    int n;

    while ((n = read(client->sockfd, buffer, sizeof(buffer))) > 0) {
        // Parse the HTTP request
        char *method = strtok(buffer, " ");
        char *path = strtok(NULL, " ");
        char *version = strtok(NULL, "\r\n");

        // Check if the request is valid
        if (strcmp(method, "GET") != 0 || strcmp(version, "HTTP/1.1") != 0) {
            write(client->sockfd, "HTTP/1.1 400 Bad Request\r\n\r\n", 32);
            close(client->sockfd);
            return NULL;
        }

        // Connect to the remote server
        int remote_sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (remote_sockfd == -1) {
            write(client->sockfd, "HTTP/1.1 500 Internal Server Error\r\n\r\n", 39);
            close(client->sockfd);
            return NULL;
        }

        struct sockaddr_in remote_addr;
        remote_addr.sin_family = AF_INET;
        remote_addr.sin_port = htons(80);
        remote_addr.sin_addr.s_addr = inet_addr("127.0.0.1");

        if (connect(remote_sockfd, (struct sockaddr *)&remote_addr, sizeof(remote_addr)) == -1) {
            write(client->sockfd, "HTTP/1.1 500 Internal Server Error\r\n\r\n", 39);
            close(client->sockfd);
            return NULL;
        }

        // Forward the request to the remote server
        write(remote_sockfd, buffer, n);

        // Read the response from the remote server
        while ((n = read(remote_sockfd, buffer, sizeof(buffer))) > 0) {
            // Forward the response to the client
            write(client->sockfd, buffer, n);
        }

        // Close the connections
        close(client->sockfd);
        close(remote_sockfd);
    }

    return NULL;
}

int main(int argc, char **argv) {
    proxy.num_clients = 0;

    int listen_sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_sockfd == -1) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in listen_addr;
    listen_addr.sin_family = AF_INET;
    listen_addr.sin_port = htons(8080);
    listen_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(listen_sockfd, (struct sockaddr *)&listen_addr, sizeof(listen_addr)) == -1) {
        perror("bind");
        return -1;
    }

    if (listen(listen_sockfd, MAX_CLIENTS) == -1) {
        perror("listen");
        return -1;
    }

    while (1) {
        client_t client;
        socklen_t len = sizeof(client.addr);

        client.sockfd = accept(listen_sockfd, (struct sockaddr *)&client.addr, &len);
        if (client.sockfd == -1) {
            perror("accept");
            continue;
        }

        if (proxy.num_clients >= MAX_CLIENTS) {
            write(client.sockfd, "HTTP/1.1 503 Service Unavailable\r\n\r\n", 36);
            close(client.sockfd);
            continue;
        }

        proxy.clients[proxy.num_clients++] = client;

        pthread_t thread;
        pthread_create(&thread, NULL, handle_client, &client);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

// Function to calculate subnet mask
void calculate_subnet_mask(int subnet_prefix) {
    unsigned int mask = (0xFFFFFFFF << (32 - subnet_prefix)) & 0xFFFFFFFF;
    struct in_addr addr;
    addr.s_addr = htonl(mask);
    printf("Subnet Mask: %s\n", inet_ntoa(addr));
}

// Function to calculate the network address
void calculate_network_address(const char *ip, int subnet_prefix) {
    struct in_addr ip_addr;
    inet_aton(ip, &ip_addr);
    unsigned int mask = (0xFFFFFFFF << (32 - subnet_prefix)) & 0xFFFFFFFF;

    unsigned int network_address = ip_addr.s_addr & htonl(mask);
    struct in_addr network_addr;
    network_addr.s_addr = network_address;    
    printf("Network Address: %s\n", inet_ntoa(network_addr));
}

// Function to calculate broadcast address
void calculate_broadcast_address(const char *ip, int subnet_prefix) {
    struct in_addr ip_addr;
    inet_aton(ip, &ip_addr);

    unsigned int mask = (0xFFFFFFFF << (32 - subnet_prefix)) & 0xFFFFFFFF;
    unsigned int broadcast_address = (ip_addr.s_addr & htonl(mask)) | ~htonl(mask);

    struct in_addr broadcast_addr;
    broadcast_addr.s_addr = broadcast_address;
    printf("Broadcast Address: %s\n", inet_ntoa(broadcast_addr));
}

// Function to calculate total number of hosts
void calculate_total_hosts(int subnet_prefix) {
    int number_of_hosts = (1 << (32 - subnet_prefix)) - 2; // Subtracting 2 for network and broadcast address
    printf("Total Hosts: %d\n", number_of_hosts);
}

// Function to validate IP address
int is_valid_ip(const char *ip) {
    struct in_addr ip_addr;
    return inet_aton(ip, &ip_addr);
}

// Function to display menu
void display_menu() {
    printf("\n----- C Subnet Calculator -----\n");
    printf("1. Calculate Subnet Mask\n");
    printf("2. Calculate Network Address\n");
    printf("3. Calculate Broadcast Address\n");
    printf("4. Calculate Total Hosts\n");
    printf("5. Exit\n");
    printf("-------------------------------\n");
    printf("Enter your choice: ");
}

int main() {
    char ip[16];
    int subnet_prefix;
    int choice;

    while (1) {
        display_menu();
        scanf("%d", &choice);

        if (choice == 5) {
            break;
        }

        printf("Enter IP address (e.g., 192.168.1.1): ");
        scanf("%s", ip);

        if (!is_valid_ip(ip)) {
            printf("Invalid IP Address. Please enter a valid IP.\n");
            continue;
        }

        printf("Enter Subnet Prefix (e.g., 24): ");
        scanf("%d", &subnet_prefix);

        if (subnet_prefix < 0 || subnet_prefix > 32) {
            printf("Invalid subnet prefix. Please enter a value between 0 and 32.\n");
            continue;
        }

        switch (choice) {
            case 1:
                calculate_subnet_mask(subnet_prefix);
                break;
            case 2:
                calculate_network_address(ip, subnet_prefix);
                break;
            case 3:
                calculate_broadcast_address(ip, subnet_prefix);
                break;
            case 4:
                calculate_total_hosts(subnet_prefix);
                break;
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    printf("Exiting Subnet Calculator. Thank you!\n");
    return 0;
}

                 const u_char *p, u_int length, u_int orig_caplen, int pad,
