char *replace_word(char *string, char *word) {
    char *new_string = malloc(strlen(string) + 1);
    char *ptr = string;
    char *new_ptr = new_string;

    while (*ptr != '\0') {
        if (strcmp(ptr, word) == 0) {
            *new_ptr++ = '*';
            *new_ptr++ = ' ';
            ptr++;
        } else {
            *new_ptr++ = *ptr++;
        }
    }

    *new_ptr = '\0';

    return new_string;
}

