        fprintf(stderr, "USAGE: %s <input_file> <output_file> <flip|brightness|contrast> <brightness/contrast_value> <image_file>\n", argv[0]);
        return -1;
    }

    inputFile = fopen(argv[1], "r");
    outputFile = fopen(argv[2], "w");

