#define MAX_METADATA_SIZE 1024
#define MAX_FILE_SIZE 1024*1024

struct metadata {
  char title[MAX_METADATA_SIZE];
  char artist[MAX_METADATA_SIZE];
  char album[MAX_METADATA_SIZE];
  int year;
  int track_number;
  int duration;
};

int extract_metadata(const char *file_path, struct metadata *metadata) {
  // Open the file
  FILE *file = fopen(file_path, "rb");
  if (file == NULL) {
    return -1;
  }

  // Read the file into a buffer
  fseek(file, 0, SEEK_END);
  long file_size = ftell(file);
  rewind(file);
  char *buffer = malloc(file_size);
  if (buffer == NULL) {
    fclose(file);
    return -1;
  }
  fread(buffer, file_size, 1, file);
  fclose(file);

  // Search for the metadata tags
  const char *title_tag = "Title: ";
  const char *artist_tag = "Artist: ";
  const char *album_tag = "Album: ";
  const char *year_tag = "Year: ";
  const char *track_number_tag = "Track Number: ";
  const char *duration_tag = "Duration: ";

  char *title_start = strstr(buffer, title_tag);
  char *artist_start = strstr(buffer, artist_tag);
  char *album_start = strstr(buffer, album_tag);
  char *year_start = strstr(buffer, year_tag);
  char *track_number_start = strstr(buffer, track_number_tag);
  char *duration_start = strstr(buffer, duration_tag);

  if (title_start == NULL || artist_start == NULL || album_start == NULL || year_start == NULL || track_number_start == NULL || duration_start == NULL) {
    free(buffer);
    return -1;
  }

  // Extract the metadata values
  strcpy(metadata->title, title_start + strlen(title_tag));
  strcpy(metadata->artist, artist_start + strlen(artist_tag));
  strcpy(metadata->album, album_start + strlen(album_tag));
  metadata->year = atoi(year_start + strlen(year_tag));
  metadata->track_number = atoi(track_number_start + strlen(track_number_tag));
  metadata->duration = atoi(duration_start + strlen(duration_tag));

  // Free the buffer
  free(buffer);

  return 0;
}

int main(void) {
  // Declare the metadata structure
  struct metadata metadata;

  // Extract the metadata from a file
  int result = extract_metadata("song.mp3", &metadata);
  if (result != 0) {
    printf("Error extracting metadata\n");
    return 1;
  }

  // Print the metadata
  printf("Title: %s\n", metadata.title);
  printf("Artist: %s\n", metadata.artist);
  printf("Album: %s\n", metadata.album);
  printf("Year: %d\n", metadata.year);
  printf("Track Number: %d\n", metadata.track_number);
  printf("Duration: %d seconds\n", metadata.duration);

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define SMTP_PORT 25
#define BUFFER_SIZE 1024

void error(const char *msg) {
    perror(msg);
    exit(1);
}

void send_command(int sockfd, const char *cmd) {
    write(sockfd, cmd, strlen(cmd));
    write(sockfd, "\r\n", 2);
}

char *receive_response(int sockfd) {
    static char buffer[BUFFER_SIZE];
    memset(buffer, 0, BUFFER_SIZE);

    int bytes_received = read(sockfd, buffer, BUFFER_SIZE - 1);
    if (bytes_received < 0) {
        error("Failed to read from socket");
    }

    return buffer;
}

void smtp_client(const char *server, const char *from, const char *to, const char *subject, const char *body) {
    int sockfd;
    struct sockaddr_in server_addr;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        error("Error opening socket");
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SMTP_PORT);
    server_addr.sin_addr.s_addr = inet_addr(server);

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        error("Connection failed");
    }

    // Receive welcome message
    printf("%s", receive_response(sockfd));

    // HELO command
    send_command(sockfd, "HELO localhost");
    printf("%s", receive_response(sockfd));

    // MAIL FROM command
    char mail_from_cmd[BUFFER_SIZE];
    snprintf(mail_from_cmd, sizeof(mail_from_cmd), "MAIL FROM: <%s>", from);
    send_command(sockfd, mail_from_cmd);
    printf("%s", receive_response(sockfd));

    // RCPT TO command
    char rcpt_to_cmd[BUFFER_SIZE];
    snprintf(rcpt_to_cmd, sizeof(rcpt_to_cmd), "RCPT TO: <%s>", to);
    send_command(sockfd, rcpt_to_cmd);
    printf("%s", receive_response(sockfd));

    // DATA command
    send_command(sockfd, "DATA");
    printf("%s", receive_response(sockfd));

    // Construct email message
    char email_message[BUFFER_SIZE];
    snprintf(email_message, sizeof(email_message), "Subject: %s\r\nFrom: %s\r\nTo: %s\r\n\r\n%s\r\n.", subject, from, to, body);

    // Send email data
    send_command(sockfd, email_message);
    printf("%s", receive_response(sockfd));

    // QUIT command
    send_command(sockfd, "QUIT");
    printf("%s", receive_response(sockfd));

    // Close the socket
    close(sockfd);
}

int main() {
    const char *smtp_server = "127.0.0.1"; // SMTP server address
    const char *from_address = "sender@example.com"; // Sender's email address
    const char *to_address = "receiver@example.com"; // Receiver's email address
    const char *email_subject = "Artistic Journey"; // Subject of the email
    const char *email_body = "Greetings,\n\nWelcome to an artistic SMTP client written in C!\n\nBest Regards,\nYour SMTP Client"; // Email body

    smtp_client(smtp_server, from_address, to_address, email_subject, email_body);

    return 0;
}

