#define MAX_WIDTH 100
#define MAX_HEIGHT 100

// ASCII characters for different shades of gray
char *ascii_chars[] = {" ", ".", ":", "-", "=", "+", "*", "#", "%", "@"};

// Convert RGB values to grayscale
int get_grayscale(uint8_t r, uint8_t g, uint8_t b) {
    return (r * 0.2126 + g * 0.7152 + b * 0.0722);
}

int main(int argc, char **argv) {
    // Open image file
    FILE *infile = fopen(argv[1], "rb");
    if (!infile) {
        fprintf(stderr, "Error opening file: %s\n", argv[1]);
        return 1;
    }

    // Read image header
    char magic[2];
    int width, height, maxval;
    fscanf(infile, "%2s\n%d %d\n%d\n", magic, &width, &height, &maxval);

    // Check if image is valid
    if (magic[0] != 'P' || magic[1] != '6') {
        fprintf(stderr, "Invalid image format: %s\n", argv[1]);
        fclose(infile);
        return 1;
    }

    // Allocate memory for image data
    uint8_t *data = (uint8_t *)malloc(width * height * 3 * sizeof(uint8_t));
    if (!data) {
        fprintf(stderr, "Error allocating memory\n");
        fclose(infile);
        return 1;
    }

    // Read image data
    fread(data, sizeof(uint8_t), width * height * 3, infile);

    // Close image file
    fclose(infile);

    // Convert image to ASCII art
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            // Compute grayscale value
            int gray = get_grayscale(data[(y * width + x) * 3],
                                      data[(y * width + x) * 3 + 1],
                                      data[(y * width + x) * 3 + 2]);

            // Map grayscale value to ASCII character
            int index = gray * 10 / 255;
            printf("%s", ascii_chars[index]);
        }
        printf("\n");
    }

    // Free memory
    free(data);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_FILE_NAME_LENGTH 256
#define MAX_LINE_LENGTH 1024

typedef struct {
    char file_name[MAX_FILE_NAME_LENGTH];
    FILE *file;
    char line[MAX_LINE_LENGTH];
} File;

void open_file(File *file, const char *file_name) {
    file->file = fopen(file_name, "r");
    if (file->file == NULL) {
        printf("Error: could not open file '%s'\n", file_name);
        exit(1);
    }
}

bool read_line(File *file, char *line) {
    return fgets(file->line, MAX_LINE_LENGTH, file->file)!= NULL;
}

void close_file(File *file) {
    fclose(file->file);
}

int main() {
    int num_files;
    char file_names[MAX_FILE_NAME_LENGTH];
    File files[10];

    printf("Enter the number of files to synchronize: ");
    scanf("%d", &num_files);

    printf("Enter the file names:\n");
    for (int i = 0; i < num_files; i++) {
        scanf("%s", file_names + i * MAX_FILE_NAME_LENGTH);
    }

    for (int i = 0; i < num_files; i++) {
        strcpy(files[i].file_name, file_names + i * MAX_FILE_NAME_LENGTH);
        open_file(&files[i], files[i].file_name);
    }

    bool end_of_file = false;
    while (!end_of_file) {
        for (int i = 0; i < num_files; i++) {
            if (!read_line(&files[i], files[i].line)) {
                close_file(&files[i]);
                end_of_file = true;
                break;
            }
        }

        for (int i = 0; i < num_files - 1; i++) {
            if (strcmp(files[i].line, files[i + 1].line)!= 0) {
                printf("Files are not synchronized!\n");
                close_file(&files[i]);
                close_file(&files[i + 1]);
                end_of_file = true;
                break;
            }
        }
    }

    printf("Files are synchronized!\n");

    return 0;
}

