      if (bullet_x[i] >= invader_x && bullet_x[i] <= invader_x + invader_WIDTH && bullet_y[i] >= invader_y && bullet_y[i] <= invader_y + invader_HEIGHT)
      {
        map[invader_y][invader_x] = 1;
        bullet_x[i] = -1;
        bullet_y[i] = -1;
      }
