        }
        else
        {
          printf(" ");
        }
      }
      printf("\n");
    }

    // Draw the invader
    printf("o");

    // Draw the player
    printf("x");

    // Draw the bullets
    for (int i = 0; i < 10; i++)
    {
      if (bullet_x[i] >= 0 && bullet_x[i] < MAP_WIDTH && bullet_y[i] >= 0)
      {
        printf("o");
      }
    }

    // Update the clock
    end_time = time(NULL);
  }

  // Game over
