/* function to read an image from a file */
void read_image(char filename[], char pixels[][MAX_PIXELS], int *width, int *height)
{
    FILE *fp;
    int i, j;

    fp = fopen(filename, "r");

    if(fp == NULL) {
        printf("\nError: Unable to open the file!\n");
        exit(1);
    }

    fscanf(fp, "%d %d", width, height);

    for(i=0; i<*height; i++) {
        for(j=0; j<*width; j++) {
