#include <stdio.h>
#include <stdlib.h>

// Define a macro for image data allocation
#define IMG_ALLOC(x, y) (unsigned char *)malloc((x) * (y) * 3)

// Define a structure for image data
typedef struct ImageData
{
    unsigned char *data;
    int width;
    int height;
} ImageData;

// Function to read an image file
ImageData *readImage(char *filename)
{
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) return NULL;

    // Get the image width and height
    int width = 0;
    int height = 0;
    fscanf(fp, "%d %d", &width, &height);

    // Allocate memory for the image data
    ImageData *image = IMG_ALLOC(width, height);

    // Read the image data
    fread(image->data, 3 * width * height, 1, fp);

    // Close the file
    fclose(fp);

    return image;
}

// Function to edit an image
void editImage(ImageData *image)
{
    // Loop over the pixels
    for (int y = 0; y < image->height; y++)
    {
        for (int x = 0; x < image->width; x++)
        {
            // Get the pixel color
            unsigned char r = image->data[3 * (x, y)] & 0xff;
            unsigned char g = image->data[3 * (x, y) + 1] & 0xff;
            unsigned char b = image->data[3 * (x, y) + 2] & 0xff;

            // Modify the pixel color
            r = r + 50;
            g = g - 20;
            b = b * 2;

            // Set the pixel color
            image->data[3 * (x, y)] = r;
            image->data[3 * (x, y) + 1] = g;
            image->data[3 * (x, y) + 2] = b;
        }
    }
}

// Function to save an image file
void saveImage(ImageData *image, char *filename)
{
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) return;

    // Write the image header
    fprintf(fp, "%d %d\n", image->width, image->height);

    // Write the image data
    fwrite(image->data, 3 * image->width * image->height, 1, fp);

    // Close the file
    fclose(fp);
}

int main()
{
    // Read the image file
    ImageData *image = readImage("image.jpg");

    // Edit the image
    editImage(image);

    // Save the image file
    saveImage(image, "edited_image.jpg");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ENTRIES 1000

typedef struct {
    char name[100];
    char phone[20];
} entry_t;

entry_t phonebook[MAX_ENTRIES];
int num_entries = 0;

void add_entry() {
    char name[100], phone[20];
    printf("Enter name: ");
    scanf("%s", name);
    printf("Enter phone number: ");
    scanf("%s", phone);

    strcpy(phonebook[num_entries].name, name);
    strcpy(phonebook[num_entries].phone, phone);

    num_entries++;
}

void search_entry() {
    char name[100];
    printf("Enter name to search: ");
    scanf("%s", name);

    for (int i = 0; i < num_entries; i++) {
        if (strcmp(phonebook[i].name, name) == 0) {
            printf("Name: %s\nPhone: %s\n", phonebook[i].name, phonebook[i].phone);
        }
    }
}

void delete_entry() {
    char name[100];
    printf("Enter name to delete: ");
    scanf("%s", name);

    for (int i = 0; i < num_entries; i++) {
        if (strcmp(phonebook[i].name, name) == 0) {
            for (int j = i; j < num_entries - 1; j++) {
                strcpy(phonebook[j].name, phonebook[j + 1].name);
                strcpy(phonebook[j].phone, phonebook[j + 1].phone);
            }
            num_entries--;
            break;
        }
    }
}

void display_entries() {
    for (int i = 0; i < num_entries; i++) {
        printf("Name: %s\nPhone: %s\n", phonebook[i].name, phonebook[i].phone);
    }
}

int main() {
    int choice;

    do {
        printf("\nPhone Book\n");
        printf("1. Add Entry\n2. Search Entry\n3. Delete Entry\n4. Display Entries\n5. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch(choice) {
            case 1:
                add_entry();
                break;
            case 2:
                search_entry();
                break;
            case 3:
                delete_entry();
                break;
            case 4:
                display_entries();
                break;
            case 5:
                exit(0);
            default:
                printf("Invalid choice!\n");
        }
    } while(1);

    return 0;
}

#include <stdio.h>

// Function to calculate Fibonacci number

int fibonacci(int n)
{
    if (n == 0 || n == 1)
    {
        return n;
    }
    else
    {
        return fibonacci(n - 1) + fibonacci(n - 2);
    }
}

// Function to print the Fibonacci series upto n numbers

void print_fibonacci_series(int n)
{
    int i;

    printf("Fibonacci Series:\n");

    for (i = 0; i < n; i++)
    {
        printf("%d ", fibonacci(i));
    }

    printf("\n");
}

// Function to calculate factorial of a number

int factorial(int n)
{
    if (n == 0 || n == 1)
    {
        return 1;
    }
    else
    {
        return n * factorial(n - 1);
    }
}

// Function to print the factorial of a number

void print_factorial(int n)
{
    int fact;

    fact = factorial(n);

    printf("Factorial of %d: %d\n", n, fact);
}

int main()
{
    int n;

    printf("Enter the value of n: ");
    scanf("%d", &n);

    print_fibonacci_series(n);

    print_factorial(n);

    return 0;
}

#include <stdio.h>
