#define MAX_WORD_LENGTH 50
#define MAX_NUM_WORDS 10000

/* Struct to store the word and its frequency */
struct WordFreq {
    char word[MAX_WORD_LENGTH];
    int freq;
};
typedef struct WordFreq WordFreq;

/* Function to check if a given character is a letter */
int isLetter(char c) {
    return isalpha(c) || c == '\'';
}

/* Function to read in words from a file and count their frequency */
int readWords(FILE* fp, WordFreq* wordFreqs) {
    char word[MAX_WORD_LENGTH];
    int numWords = 0;
    while (fscanf(fp, "%s", word) != EOF) {
        // Remove punctuation from end of word
        int len = strlen(word);
        while (len > 0 && !isLetter(word[len - 1])) {
            word[len - 1] = '\0';
            len--;
        }
        // Remove punctuation from beginning of word
        int start = 0;
        while (start < len && !isLetter(word[start])) {
            start++;
        }
        // Add word to frequency array
        if (start < len) {
            // Convert word to lowercase
            for (int i = start; i < len; i++) {
                word[i] = tolower(word[i]);
            }
            // Check if word already exists in frequency array
            int found = 0;
            for (int i = 0; i < numWords; i++) {
                if (strcmp(word, wordFreqs[i].word) == 0) {
                    wordFreqs[i].freq++;
                    found = 1;
                    break;
                }
            }
            // Add new word to frequency array
            if (!found) {
                strcpy(wordFreqs[numWords].word, word);
                wordFreqs[numWords].freq = 1;
                numWords++;
            }
        }
        // Check if maximum number of words has been reached
        if (numWords == MAX_NUM_WORDS) {
            break;
        }
    }
    return numWords;
}

/* Function to sort the frequency array by frequency in descending order */
void sortFreqs(WordFreq* wordFreqs, int numWords) {
    // Bubble sort the frequency array in descending order
    for (int i = 0; i < numWords - 1; i++) {
        for (int j = 0; j < numWords - i - 1; j++) {
            if (wordFreqs[j].freq < wordFreqs[j + 1].freq) {
                WordFreq temp = wordFreqs[j];
                wordFreqs[j] = wordFreqs[j + 1];
                wordFreqs[j + 1] = temp;
            }
        }
    }
}

/* Function to print the frequency array */
void printFreqs(WordFreq* wordFreqs, int numWords) {
    printf("Word Frequency\n");
    for (int i = 0; i < numWords; i++) {
        printf("%-15s %d\n", wordFreqs[i].word, wordFreqs[i].freq);
    }
}

/* Main function */
int main(int argc, char** argv) {
    // Check command line arguments
    if (argc != 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        exit(1);
    }
    // Open file for reading
    FILE* fp = fopen(argv[1], "r");
    if (fp == NULL) {
        printf("Error: could not open file '%s'\n", argv[1]);
        exit(1);
    }
    // Read words from file and count their frequency
    WordFreq wordFreqs[MAX_NUM_WORDS];
    int numWords = readWords(fp, wordFreqs);
    // Sort the frequency array by frequency in descending order
    sortFreqs(wordFreqs, numWords);
    // Print the frequency array
    printFreqs(wordFreqs, numWords);
    // Close file
    fclose(fp);
    // Exit program
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PIXEL 255

#define RED 0
#define GREEN 1
#define BLUE 2

typedef struct Pixel {
    unsigned char r;     // red component
    unsigned char g;     // green component
    unsigned char b;     // blue component
} Pixel;

typedef struct Image {
    int width;           // width of image
    int height;          // height of image
    Pixel *data;         // array of pixels
} Image;

// allocate memory for an image of the given width and height
Image *create_image(int width, int height) {
    Image *image = (Image*) malloc(sizeof(Image));
    image->width = width;
    image->height = height;
    image->data = (Pixel*) malloc(width * height * sizeof(Pixel));
    return image;
}

// free memory allocated for an image
void delete_image(Image *image) {
    free(image->data);
    free(image);
}

// read image data from a file
Image *read_image(const char *filename) {
    // open file for reading
    FILE *file = fopen(filename, "r");

    // check if file was opened successfully
    if (file == NULL) {
        printf("Error: could not open file '%s'\n", filename);
        return NULL;
    }

    // read image dimensions from file
    int width, height;
    fscanf(file, "%d %d", &width, &height);

    // create image object
    Image *image = create_image(width, height);

    // read pixel data from file
    for (int i = 0; i < width * height; i++) {
        fscanf(file, "%hhu %hhu %hhu", &image->data[i].r, &image->data[i].g, &image->data[i].b);
    }

    // close file
    fclose(file);

    return image;
}

// write image data to a file
void write_image(const char *filename, Image *image) {
    // open file for writing
    FILE *file = fopen(filename, "w");

    // write image dimensions to file
    fprintf(file, "%d %d\n", image->width, image->height);

    // write pixel data to file
    for (int i = 0; i < image->width * image->height; i++) {
        fprintf(file, "%hhu %hhu %hhu\n", image->data[i].r, image->data[i].g, image->data[i].b);
    }

    // close file
    fclose(file);
}

// flip image vertically
void flip_vertical(Image *image) {
    int half_height = image->height / 2;
    for (int y = 0; y < half_height; y++) {
        for (int x = 0; x < image->width; x++) {
            Pixel temp = image->data[y * image->width + x];
            image->data[y * image->width + x] = image->data[(image->height - 1 - y) * image->width + x];
            image->data[(image->height - 1 - y) * image->width + x] = temp;
        }
    }
}

// apply grayscale filter to image
void grayscale_filter(Image *image) {
    for (int i = 0; i < image->width * image->height; i++) {
        unsigned char gray = (image->data[i].r + image->data[i].g + image->data[i].b) / 3;
        image->data[i].r = gray;
        image->data[i].g = gray;
        image->data[i].b = gray;
    }
}

// apply red filter to image
void red_filter(Image *image) {
    for (int i = 0; i < image->width * image->height; i++) {
        image->data[i].g = 0;
        image->data[i].b = 0;
    }
}

int main() {
    // read image from file
    Image *image = read_image("input.ppm");

    // apply filters
    flip_vertical(image);
    grayscale_filter(image);
    red_filter(image);

    // write image to file
    write_image("output.ppm", image);

    // free memory allocated for image
    delete_image(image);

    // return success
    return 0;
}

