// A Calm Image Editor in C

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <math.h>

#define WIDTH 640
#define HEIGHT 480
#define BITS_PER_PIXEL 32

// Structure to hold the image data
typedef struct {
    unsigned char *data;
    int width, height, bits_per_pixel;
} image_t;

// Function to create a new image
image_t *new_image(int width, int height, int bits_per_pixel) {
    image_t *img = (image_t *)calloc(1, sizeof(image_t));
    img->width = width;
    img->height = height;
    img->bits_per_pixel = bits_per_pixel;
    img->data = (unsigned char *)calloc(width * height, bits_per_pixel / 8);
    return img;
}

// Function to load an image from a file
image_t *load_image(const char *filename) {
    int width, height, bits_per_pixel;
    image_t *img = NULL;

    // Open the image file and read its dimensions and bits per pixel
    FILE *file = fopen(filename, "rb");
    fread(&width, sizeof(int), 1, file);
    fread(&height, sizeof(int), 1, file);
    fread(&bits_per_pixel, sizeof(int), 1, file);

    // Allocate memory for the image data
    img = new_image(width, height, bits_per_pixel);

    // Read the image data from the file and store it in the image structure
    fread(img->data, bits_per_pixel / 8, width * height, file);

    fclose(file);

    return img;
}

// Function to save an image to a file
void save_image(const char *filename, image_t *img) {
    int width, height, bits_per_pixel;

    // Open the image file for writing
    FILE *file = fopen(filename, "wb");

    // Write the image dimensions and bits per pixel to the file
    fwrite(&width, sizeof(int), 1, file);
    fwrite(&height, sizeof(int), 1, file);
    fwrite(&bits_per_pixel, sizeof(int), 1, file);

    // Write the image data to the file
    fwrite(img->data, bits_per_pixel / 8, width * height, file);

    fclose(file);
}

// Function to display the image
void display_image(image_t *img) {
    int i, j;
    for (i = 0; i < img->height; i++) {
        for (j = 0; j < img->width; j++) {
            printf("%02x", img->data[i * img->width * BITS_PER_PIXEL + j * BITS_PER_PIXEL]);
        }
        printf("\n");
    }
}

int main() {
    image_t *img = load_image("example.bmp");
    display_image(img);
    save_image("output.bmp", img);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_CLIENTS 10
#define BUFFER_SIZE 1024

struct client_info {
    int sock;
    char ip[INET6_ADDRSTRLEN];
    char name[20];
};

void *handle_client(void *arg) {
    struct client_info *client = (struct client_info *) arg;
    char buffer[BUFFER_SIZE];

    while (1) {
        memset(buffer, 0, BUFFER_SIZE);
        int bytes_received = recv(client->sock, buffer, BUFFER_SIZE, 0);

        if (bytes_received <= 0) {
            break;
        }

        send(client->sock, buffer, bytes_received, 0);
    }

    close(client->sock);
    printf("Client disconnected: %s\n", client->name);
}

int main() {
    int server_sock = socket(AF_INET, SOCK_STREAM, 0);

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    bind(server_sock, (struct sockaddr *) &server_addr, sizeof(server_addr));
    listen(server_sock, MAX_CLIENTS);

    printf("Chat server started on port 8080\n");

    while (1) {
        struct client_info client_info;
        socklen_t client_size = sizeof(client_info.ip);

        int client_sock = accept(server_sock, (struct sockaddr *) &client_info.ip, &client_size);

        if (client_sock == -1) {
            printf("Error accepting client\n");
            continue;
        }

        inet_ntop(AF_INET, &client_info.ip, client_info.ip, INET6_ADDRSTRLEN);

        printf("Client connected: %s\n", client_info.ip);

        pthread_t thread_id;
        pthread_create(&thread_id, NULL, handle_client, (void *) &client_info);
    }

    return 0;
}

