        if (strchr(invalid_chars, url[i])!= NULL) {
            url[i] = '%';
            len += 2;
            url = realloc(url, len + 1);
            sprintf(&url[i + 1], "%02X", (unsigned char)url[i]);
        }
    }

    output_url.url = url;
    output_url.len = len;

    return output_url;
}

// function to print a URL
void print_url(const url_t *url) {
    printf("%s\n", url->url);
}

int main() {
