#include <stdio.h>
#include <stdlib.h>

#define MAX 10

typedef struct Node {
  int data;
  struct Node* next;
} Node;

typedef struct Graph {
  Node** graph;
  int numVertices;
} Graph;

void insertVertex(Graph* g, int data) {
  g->numVertices++;
  g->graph = (Node**)realloc(g->graph, g->numVertices * sizeof(Node*));
  g->graph[g->numVertices - 1] = (Node*)malloc(sizeof(Node));
  g->graph[g->numVertices - 1]->data = data;
  g->graph[g->numVertices - 1]->next = NULL;
}

void insertEdge(Graph* g, int src, int dest) {
  Node* newNode = (Node*)malloc(sizeof(Node));
  newNode->data = dest;
  newNode->next = NULL;

  insertVertex(g, src);

  g->graph[src]->next = newNode;
}

int main() {
  Graph* g = (Graph*)malloc(sizeof(Graph));
  g->numVertices = 0;
  g->graph = NULL;

  insertVertex(g, 1);
  insertVertex(g, 2);
  insertVertex(g, 3);
  insertVertex(g, 4);
  insertVertex(g, 5);

  insertEdge(g, 1, 2);
  insertEdge(g, 2, 3);
  insertEdge(g, 3, 4);
  insertEdge(g, 4, 5);

  for (int i = 0; i < g->numVertices; i++) {
    printf("%d ", g->graph[i]->data);
  }

  printf("\n");

  for (int i = 0; i < g->numVertices; i++) {
    for (Node* node = g->graph[i]->next; node; node = node->next) {
      printf("%d ", node->data);
    }
  }

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILE_NAME_LEN 256
#define MAX_PIXEL_SIZE 1024

typedef struct RGBPixel{
    unsigned char red;
    unsigned char green;
    unsigned char blue;
} RGBPixel;

int main(){
    char file_name[MAX_FILE_NAME_LEN];
    printf("Enter the image file name: ");
    fgets(file_name, MAX_FILE_NAME_LEN, stdin);

    // Removing the newline character from the file name
    file_name[strcspn(file_name, "\n")] = 0;

    FILE *input_file = fopen(file_name, "rb");
    if(input_file == NULL){
        printf("Error opening file!");
        return 1;
    }

    RGBPixel pixel_array[MAX_PIXEL_SIZE][MAX_PIXEL_SIZE];
    int width, height;

    // Reading the image header to extract the width and height
    fscanf(input_file, "P6 %d %d 255", &width, &height);

    // Reading the image pixel data into the 2D array
    for(int i=0; i<height; i++){
        for(int j=0; j<width; j++){
            fread(&pixel_array[i][j], sizeof(RGBPixel), 1, input_file);
        }
    }

    fclose(input_file);

    // Applying a simple filter to invert the colors
    for(int i=0; i<height; i++){
        for(int j=0; j<width; j++){
            pixel_array[i][j].red = 255 - pixel_array[i][j].red;
            pixel_array[i][j].green = 255 - pixel_array[i][j].green;
            pixel_array[i][j].blue = 255 - pixel_array[i][j].blue;
        }
    }

    // Writing the modified pixel data to a new file
    FILE *output_file = fopen("inverted_image.ppm", "wb");
    fprintf(output_file, "P6\n%d %d\n255\n", width, height);
    for(int i=0; i<height; i++){
        for(int j=0; j<width; j++){
            fwrite(&pixel_array[i][j], sizeof(RGBPixel), 1, output_file);
        }
    }
    fclose(output_file);

    printf("Image saved successfully!");

    return 0;
}

#include <stdio.h>
#include <string.h>

struct csv_row {
    char *first_name;
    char *last_name;
    int age;
    double salary;
};

void print_csv_row(const struct csv_row *row) {
    printf("%s, %s, %d, %.2f\n", row->first_name, row->last_name, row->age, row->salary);
}

int main() {
    FILE *csv_file = fopen("example.csv", "r");
    if (csv_file == NULL) {
        printf("Error opening file\n");
        return 1;
    }

    struct csv_row csv_row;
    char c;

    while ((c = fgetc(csv_file))!= EOF) {
        if (c == '\n') {
            print_csv_row(&csv_row);
            csv_row.first_name = NULL;
            csv_row.last_name = NULL;
            csv_row.age = 0;
            csv_row.salary = 0.0;
        }
        else if (c == ',') {
            csv_row.first_name = NULL;
            csv_row.last_name = NULL;
            csv_row.age = 0;
            csv_row.salary = 0.0;
        }
        else if (c == '\"') {
            if (csv_row.first_name == NULL) {
                csv_row.first_name = malloc(strlen(c) + 1);
                if (csv_row.first_name == NULL) {
                    fprintf(stderr, "Error allocating memory for first name\n");
                    return 1;
                }
                memcpy(csv_row.first_name, c, strlen(c));
                csv_row.first_name[strlen(c)] = '\0';
            }
            else if (csv_row.last_name == NULL) {
                csv_row.last_name = malloc(strlen(c) + 1);
                if (csv_row.last_name == NULL) {
                    fprintf(stderr, "Error allocating memory for last name\n");
                    return 1;
                }
                memcpy(csv_row.last_name, c, strlen(c));
                csv_row.last_name[strlen(c)] = '\0';
            }
            else if (csv_row.age == 0) {
                csv_row.age = atoi(c);
            }
            else if (csv_row.salary == 0.0) {
                csv_row.salary = atof(c);
            }
        }
        else {
            if (csv_row.first_name!= NULL) {
                csv_row.first_name = strcat(csv_row.first_name, c);
            }
            else if (csv_row.last_name!= NULL) {
                csv_row.last_name = strcat(csv_row.last_name, c);
            }
            else if (csv_row.age!= 0) {
                csv_row.age = csv_row.age * 10 + atoi(c);
            }
            else if (csv_row.salary!= 0.0) {
                csv_row.salary = csv_row.salary * 100 + atof(c);
            }
        }
    }

    fclose(csv_file);
    return 0;
}

