            monsters[i].pos.x = rand() % MAP_WIDTH;
            monsters[i].pos.y = rand() % MAP_HEIGHT;
        }

        monsters[i].health = 10; // Each monster has 10 health
        map[monsters[i].pos.y][monsters[i].pos.x] = MONSTER;
    }
}

