} Account;

Account accounts[MAX_ACCOUNTS];
int accountCount = 0;

void displayMenu();
void createAccount();
void deposit();
void withdraw();
void viewAccount();
void listAccounts();
int findAccountIndex(char *accountNumber);

int main() {
    int choice;

    do {
        displayMenu();
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                createAccount();
                break;
            case 2:
                deposit();
                break;
            case 3:
                withdraw();
                break;
            case 4:
                viewAccount();
                break;
            case 5:
                listAccounts();
