void display_image(Image *image) {
  for (int y = 0; y < image->height; y++) {
    for (int x = 0; x < image->width; x++) {
      int offset = (y * image->width + x) * image->channels;
      printf("%c", image->data[offset]);
    }
    printf("\n");
  }
}

