    // Create an array of pointers to the rows
    csv_data = malloc(num_rows * sizeof(char *));
    if (csv_data == NULL)
    {
        return EXIT_FAILURE;
    }

    // Copy the rows from the buffer to the CSV_data array
    for (size_t i = 0; i < num_rows; i++)
    {
        csv_data[i] = strdup(buffer);
