#include <stdio.h>
#include <stdlib.h>

#define SIZE 8

typedef enum { EMPTY, BLACK, WHITE } Piece;
typedef struct {
    Piece board[SIZE][SIZE];
} CheckersGame;

void initializeGame(CheckersGame *game) {
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            if (i < 3 && (i + j) % 2 == 1) {
                game->board[i][j] = BLACK;
            } else if (i > 4 && (i + j) % 2 == 1) {
                game->board[i][j] = WHITE;
            } else {
                game->board[i][j] = EMPTY;
            }
        }
    }
}

void printBoard(CheckersGame *game) {
    printf("  A B C D E F G H\n");
    for (int i = 0; i < SIZE; i++) {
        printf("%d ", SIZE - i);
        for (int j = 0; j < SIZE; j++) {
            char c;
            switch (game->board[i][j]) {
                case BLACK: c = 'B'; break;
                case WHITE: c = 'W'; break;
                case EMPTY: c = '.'; break;
            }
            printf("%c ", c);
        }
        printf("\n");
    }
}

int isValidMove(CheckersGame *game, int fromRow, int fromCol, int toRow, int toCol, Piece player) {
    if (toRow < 0 || toRow >= SIZE || toCol < 0 || toCol >= SIZE) return 0;
    if (game->board[toRow][toCol] != EMPTY) return 0;

    int rowDifference = toRow - fromRow;
    int colDifference = toCol - fromCol;

    if (player == WHITE && rowDifference == -1 && abs(colDifference) == 1) return 1; // normal move
    if (player == BLACK && rowDifference == 1 && abs(colDifference) == 1) return 1; // normal move
    return 0; // invalid move
}

void movePiece(CheckersGame *game, int fromRow, int fromCol, int toRow, int toCol) {
    game->board[toRow][toCol] = game->board[fromRow][fromCol];
    game->board[fromRow][fromCol] = EMPTY;
}

int main() {
    CheckersGame game;
    initializeGame(&game);
    int fromRow, fromCol, toRow, toCol;
    char fromColChar, toColChar;
    Piece currentPlayer = BLACK;

    while (1) {
        printBoard(&game);
        printf("Player %s's turn (Input: FromRow FromCol ToRow ToCol): ", currentPlayer == BLACK ? "BLACK" : "WHITE");
        scanf(" %c%d %c%d", &fromColChar, &fromRow, &toColChar, &toRow);

        fromCol = fromColChar - 'A';
        fromRow = SIZE - fromRow; // Adjust for 0-based index
        toCol = toColChar - 'A';
        toRow = SIZE - toRow; // Adjust for 0-based index

        if (isValidMove(&game, fromRow, fromCol, toRow, toCol, currentPlayer)) {
            movePiece(&game, fromRow, fromCol, toRow, toCol);
            currentPlayer = (currentPlayer == BLACK) ? WHITE : BLACK; // Switch player
        } else {
            printf("Invalid move. Please try again.\n");
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>

#define TIME_INTERVAL 1 // Time interval in seconds

// Function to read CPU statistics from /proc/stat
void get_cpu_usage(long long *idle_time, long long *total_time) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    char buffer[256];
    fgets(buffer, sizeof(buffer), fp); // Read the first line
    fclose(fp);

    long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;

    // Parse CPU times from the line
    sscanf(buffer, "cpu %lld %lld %lld %lld %lld %lld %lld %lld %lld %lld",
           &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);

    *idle_time = idle + iowait;
    *total_time = user + nice + system + *idle_time + irq + softirq + steal + guest + guest_nice;
}

// Function to calculate CPU usage
void calculate_cpu_usage() {
    long long idle_time1, total_time1;
    long long idle_time2, total_time2;

    // Get initial CPU statistics
    get_cpu_usage(&idle_time1, &total_time1);
    sleep(TIME_INTERVAL); // Wait for the specified interval
    // Get CPU statistics after the interval
    get_cpu_usage(&idle_time2, &total_time2);

    // Calculate CPU usage
    long long idle_time_diff = idle_time2 - idle_time1;
    long long total_time_diff = total_time2 - total_time1;
    double cpu_usage = 100.0 * (1.0 - ((double)idle_time_diff / (double)total_time_diff));

    printf("CPU Usage: %.2f%%\n", cpu_usage);
}

int main() {
    printf("CPU Usage Monitor\n");
    printf("Press Ctrl+C to stop monitoring...\n");

    while (1) {
        calculate_cpu_usage();
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Struct to store contact information
struct Contact {
    char name[50];
    char phone_number[20];
    char email[100];
};

// Function to add contact to the phone book
void add_contact(struct Contact *contacts, int num_contacts) {
    char input[100];
    printf("Enter name: ");
    fgets(input, 100, stdin);
    strcpy(contacts[num_contacts].name, input);
    contacts[num_contacts].name[strcspn(contacts[num_contacts].name, "\n")] = 0; // remove newline

    printf("Enter phone number: ");
    fgets(input, 100, stdin);
    strcpy(contacts[num_contacts].phone_number, input);
    contacts[num_contacts].phone_number[strcspn(contacts[num_contacts].phone_number, "\n")] = 0; // remove newline

    printf("Enter email: ");
    fgets(input, 100, stdin);
    strcpy(contacts[num_contacts].email, input);
    contacts[num_contacts].email[strcspn(contacts[num_contacts].email, "\n")] = 0; // remove newline

    printf("Contact added successfully!\n");
}

// Function to search for a contact by name
void search_contact(struct Contact *contacts, int num_contacts) {
    char search_name[50];
    printf("Enter name to search for: ");
    fgets(search_name, 50, stdin);
    search_name[strcspn(search_name, "\n")] = 0; // remove newline

    int found = 0;
    for (int i = 0; i < num_contacts; i++) {
        if (strcmp(contacts[i].name, search_name) == 0) {
            printf("Name: %s\n", contacts[i].name);
            printf("Phone Number: %s\n", contacts[i].phone_number);
            printf("Email: %s\n", contacts[i].email);
            found = 1;
            break;
        }
    }
    if (!found) {
        printf("Contact not found.\n");
    }
}

int main() {
    int num_contacts = 0;
    struct Contact *contacts = malloc(sizeof(struct Contact));

    printf("Welcome to the Phone Book!\n\n");

    while (1) {
        printf("Menu:\n");
        printf("1. Add Contact\n");
        printf("2. Search Contact\n");
        printf("3. Quit\n\n");

        char input[100];
        printf("Enter choice: ");
        fgets(input, 100, stdin);

        if (strcmp(input, "1\n") == 0) {
            add_contact(contacts, num_contacts);
            num_contacts++;
            contacts = realloc(contacts, (num_contacts + 1) * sizeof(struct Contact)); // resize array
        }
        else if (strcmp(input, "2\n") == 0) {
            search_contact(contacts, num_contacts);
        }
        else if (strcmp(input, "3\n") == 0) {
            break;
        }
        else {
            printf("Invalid choice. Please try again.\n");
        }

        printf("\n");
    }

    free(contacts);

    return 0;
}

// A C program to simulate a classical circuit.
// The circuit is described by a netlist file.
// The netlist file is parsed and a graph is created to represent the circuit.
// The graph is then simulated using a modified version of the Gauss-Seidel method.

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// A node in the graph.
typedef struct node {
    char *name;
    int num_inputs;
    int *inputs;
    int output;
} node;

// A graph representing a circuit.
typedef struct graph {
    int num_nodes;
    node *nodes;
} graph;

// Parses a netlist file and creates a graph representing the circuit.
graph *parse_netlist(char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", filename);
        return NULL;
    }

    // Read the number of nodes in the circuit.
    int num_nodes;
    fscanf(fp, "%d", &num_nodes);

    // Create a graph to represent the circuit.
    graph *g = malloc(sizeof(graph));
    g->num_nodes = num_nodes;
    g->nodes = malloc(sizeof(node) * num_nodes);

    // Read the nodes from the netlist file.
    for (int i = 0; i < num_nodes; i++) {
        node *n = &g->nodes[i];

        // Read the node's name.
        char name[256];
        fscanf(fp, "%s", name);
        n->name = strdup(name);

        // Read the number of inputs to the node.
        fscanf(fp, "%d", &n->num_inputs);

        // Read the node's inputs.
        n->inputs = malloc(sizeof(int) * n->num_inputs);
        for (int j = 0; j < n->num_inputs; j++) {
            fscanf(fp, "%d", &n->inputs[j]);
        }

        // Read the node's output.
        fscanf(fp, "%d", &n->output);
    }

    fclose(fp);

    return g;
}

// Simulates a graph representing a circuit using a modified version of the Gauss-Seidel method.
void simulate(graph *g) {
    // Initialize the node outputs to 0.
    for (int i = 0; i < g->num_nodes; i++) {
        g->nodes[i].output = 0;
    }

    // Iterate over the nodes until the outputs converge.
    int converged = 0;
    while (!converged) {
        converged = 1;

        // Iterate over the nodes.
        for (int i = 0; i < g->num_nodes; i++) {
            node *n = &g->nodes[i];

            // Calculate the node's output.
            int output = 0;
            for (int j = 0; j < n->num_inputs; j++) {
                output += g->nodes[n->inputs[j]].output;
            }

            // Update the node's output if it has changed.
            if (output != n->output) {
                n->output = output;
                converged = 0;
            }
        }
    }
}

// Prints the outputs of the nodes in a graph.
void print_outputs(graph *g) {
    for (int i = 0; i < g->num_nodes; i++) {
        node *n = &g->nodes[i];

        printf("%s: %d\n", n->name, n->output);
    }
}

// Frees the memory allocated for a graph.
void free_graph(graph *g) {
    for (int i = 0; i < g->num_nodes; i++) {
        free(g->nodes[i].name);
        free(g->nodes[i].inputs);
    }
    free(g->nodes);
    free(g);
}

// The main function.
int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <netlist file>\n", argv[0]);
        return 1;
    }

    // Parse the netlist file.
    graph *g = parse_netlist(argv[1]);
    if (g == NULL) {
        return 1;
    }

    // Simulate the circuit.
    simulate(g);

    // Print the outputs of the nodes.
    print_outputs(g);

    // Free the memory allocated for the graph.
    free_graph(g);

    return 0;
}

