php_mysqlnd_change_auth_response_write(MYSQLND_CONN_DATA * conn, void * _packet)
{
	MYSQLND_PACKET_CHANGE_AUTH_RESPONSE *packet= (MYSQLND_PACKET_CHANGE_AUTH_RESPONSE *) _packet;
	MYSQLND_ERROR_INFO * error_info = conn->error_info;
	MYSQLND_PFC * pfc = conn->protocol_frame_codec;
	MYSQLND_VIO * vio = conn->vio;
	MYSQLND_STATS * stats = conn->stats;
	MYSQLND_CONNECTION_STATE * connection_state = &conn->state;
	size_t total_packet_size = packet->auth_data_len + MYSQLND_HEADER_SIZE;
	zend_uchar * const buffer = pfc->cmd_buffer.length >= total_packet_size? pfc->cmd_buffer.buffer : mnd_emalloc(total_packet_size);
	zend_uchar * p = buffer + MYSQLND_HEADER_SIZE; /* start after the header */

	DBG_ENTER("php_mysqlnd_change_auth_response_write");

	if (packet->auth_data_len) {
		memcpy(p, packet->auth_data, packet->auth_data_len);
		p+= packet->auth_data_len;
	}

	{
		/*
		  The auth handshake packet has no command in it. Thus we can't go over conn->command directly.
		  Well, we can have a command->no_command(conn, payload)
		*/
		const size_t sent = pfc->data->m.send(pfc, vio, buffer, p - buffer - MYSQLND_HEADER_SIZE, stats, error_info);
		if (buffer != pfc->cmd_buffer.buffer) {
			mnd_efree(buffer);
		}
		if (!sent) {
			SET_CONNECTION_STATE(connection_state, CONN_QUIT_SENT);
		}
		DBG_RETURN(sent);
	}

#include <stdio.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <netdb.h>
#include <unistd.h>
#include <time.h>

#define QoS_PORT 50001
#define QoS_BUFFER_SIZE 1024

int main() {
  int sockfd, client_sockfd;
  struct sockaddr_in client_addr;
  char buffer[QoS_BUFFER_SIZE];
  time_t start_time, end_time;
  double duration, upload_rate, download_rate;

  // Create a socket
  sockfd = socket(AF_INET, SOCK_STREAM, htons(QoS_PORT));
  if (sockfd < 0) {
    perror("Error creating socket");
    exit(1);
  }

  // Listen for clients
  client_sockfd = accept(sockfd, (struct sockaddr *)&client_addr, NULL);
  if (client_sockfd < 0) {
    perror("Error accepting client");
    exit(1);
  }

  // Start the timer
  start_time = time(NULL);

  // Receive data
  int bytes_received = recv(client_sockfd, buffer, QoS_BUFFER_SIZE, 0);
  if (bytes_received < 0) {
    perror("Error receiving data");
    exit(1);
  }

  // End the timer
  end_time = time(NULL);

  // Calculate the duration, upload rate, and download rate
  duration = (double)(end_time - start_time) / CLOCKS_PER_SEC;
  upload_rate = (double)bytes_received / duration;
  download_rate = (double)bytes_received / duration;

  // Print the results
  printf("Client IP: %s\n", client_addr.sin_addr.s_addr);
  printf("Duration: %.2f seconds\n", duration);
  printf("Upload Rate: %.2f Mbps\n", upload_rate);
  printf("Download Rate: %.2f Mbps\n", download_rate);

  // Close the socket
  close(client_sockfd);
  close(sockfd);

  return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* declare global variables */
double total_cpu_time = 0.0;
double total_idle_time = 0.0;
double prev_total_cpu_time = 0.0;
double prev_total_idle_time = 0.0;
double cpu_usage = 0.0;

/* function to calculate CPU usage */
void calculate_cpu_usage() {
    /* open file pointer for cpu usage information */
    FILE* fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        printf("Error opening file!\n");
        exit(1);
    }

    /* declare variables */
    double user_time = 0.0;
    double nice_time = 0.0;
    double system_time = 0.0;
    double idle_time = 0.0;

    /* read the content of the file and extract the relevant information */
    fscanf(fp, "cpu %lf %lf %lf %lf", &user_time, &nice_time, &system_time, &idle_time);

    /* close the file pointer */
    fclose(fp);

    /* calculate the total CPU time */
    total_cpu_time = user_time + nice_time + system_time + idle_time;

    /* calculate the total idle time */
    total_idle_time = idle_time;

    /* calculate the CPU usage */
    cpu_usage = (1 - ((total_cpu_time - prev_total_cpu_time) - (total_idle_time - prev_total_idle_time)) / (total_cpu_time - prev_total_cpu_time)) * 100;

    /* update the previous values to the current values */
    prev_total_cpu_time = total_cpu_time;
    prev_total_idle_time = total_idle_time;
}

int main() {
    /* run the loop infinitely */
    while (1) {
        /* call the function to calculate CPU usage */
        calculate_cpu_usage();

        /* display the calculated CPU usage */
        printf("CPU USAGE: %.2f%%\n", cpu_usage);

        /* wait for 1 second */
        sleep(1);
    }

    return 0;
}

