#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define BUF_SIZE 128
#define SAMPLES 10

double sample_cpu_usage() {
    char buf[BUF_SIZE];
    FILE *fp;
    double user, nice, sys, idle, iowait, irq, sirq;
    double cpu_usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        printf("Error opening /proc/stat\n");
        exit(EXIT_FAILURE);
    }

    fgets(buf, BUF_SIZE, fp);

    sscanf(buf, "cpu %lf %lf %lf %lf %lf %lf %lf", &user, &nice, &sys, &idle, &iowait, &irq, &sirq);

    fclose(fp);

    static double prev_idle = 0, prev_total = 0;
    double total = user + nice + sys + idle + iowait + irq + sirq;
    double idle_diff = idle - prev_idle;
    double total_diff = total - prev_total;
    cpu_usage = 100 * (1 - (idle_diff / total_diff));

    prev_idle = idle;
    prev_total = total;

    return cpu_usage;
}

int main() {
    double cpu_usage_samples[SAMPLES];
    double cpu_usage_avg;
    int i;

    printf("CPU Usage Monitor\n\n");

    for (i = 0; i < SAMPLES; i++) {
        cpu_usage_samples[i] = sample_cpu_usage();
        printf("Sample %d: CPU Usage = %.2f%%\n", i+1, cpu_usage_samples[i]);
        sleep(1);
    }

    cpu_usage_avg = 0;
    for (i = 0; i < SAMPLES; i++) {
        cpu_usage_avg += cpu_usage_samples[i];
    }
    cpu_usage_avg /= SAMPLES;

    printf("\nAverage CPU Usage = %.2f%%\n", cpu_usage_avg);

    return 0;
}

#include <stdio.h>
#include <netdb.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <unistd.h>

#define SERVER_PORT 8888
#define BUFFER_SIZE 1024

int main() {
  int sockfd, newsockfd, clientlen;
  struct sockaddr_in server_addr, client_addr;
  char buffer[BUFFER_SIZE];
  time_t start_time, end_time;
  int bytes_sent, bytes_received, lost_packets;

  // Create a socket
  sockfd = socket(AF_INET, SOCK_STREAM, htons(SERVER_PORT));
  if (sockfd < 0) {
    perror("Error creating socket");
    return -1;
  }

  // Bind the socket to a port
  server_addr.sin_family = AF_INET;
  server_addr.sin_port = htons(SERVER_PORT);
  if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
    perror("Error binding socket");
    return -1;
  }

  // Listen for clients
  clientlen = sizeof(client_addr);
  newsockfd = accept(sockfd, (struct sockaddr *)&client_addr, &clientlen);
  if (newsockfd < 0) {
    perror("Error accepting client");
    return -1;
  }

  // Start the timer
  start_time = time(NULL);

  // Send and receive data
  bytes_sent = send(newsockfd, buffer, BUFFER_SIZE, 0);
  bytes_received = recv(newsockfd, buffer, BUFFER_SIZE, 0);

  // End the timer
  end_time = time(NULL);

  // Calculate the lost packets
  lost_packets = (bytes_sent - bytes_received) * 100 / bytes_sent;

  // Print the results
  printf("Client IP: %s\n", client_addr.sin_addr.s_addr);
  printf("Bytes sent: %d\n", bytes_sent);
  printf("Bytes received: %d\n", bytes_received);
  printf("Lost packets: %d%%\n", lost_packets);
  printf("QoS: %s\n", (bytes_received / bytes_sent) * 100);

  // Close the socket
  close(newsockfd);
  close(sockfd);

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
