int main() {
    const int BOARD_SIZE = 4;
    int board[BOARD_SIZE][BOARD_SIZE];
    int flipped[BOARD_SIZE][BOARD_SIZE];

    // Initialize the board
    int pairs[BOARD_SIZE * BOARD_SIZE / 2];
    for (int i = 0; i < BOARD_SIZE * BOARD_SIZE / 2; i++) {
        pairs[i] = i + 1;
    }
    srand(time(NULL));  // Initialize the random number generator
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            int r = rand() % (BOARD_SIZE * BOARD_SIZE / 2);
            board[i][j] = pairs[r];
            board[BOARD_SIZE - i - 1][BOARD_SIZE - j - 1] = pairs[r];
            pairs[r] = pairs[BOARD_SIZE * BOARD_SIZE / 2 - r - 1];  // Remove the used pair
        }
    }

    int num_guesses = 0;
    int score = 0;
    int game_over = 0;
    while (!game_over) {
        // Print the board
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (flipped[i][j]) {
                    printf("%2d ", board[i][j]);
                } else {
                    printf("   ");
                }
            }
            printf("\n");
        }

        // Get the user's guess
        int row1, col1, row2, col2;
        printf("Enter the row and column of your first guess: ");
        scanf("%d %d", &row1, &col1);
        row1--;
        col1--;
        printf("Enter the row and column of your second guess: ");
        scanf("%d %d", &row2, &col2);
        row2--;
        col2--;

        // Flip the cards
        flipped[row1][col1] = 1;
        flipped[row2][col2] = 1;
        num_guesses++;

        // Check if the guesses match
        if (board[row1][col1] == board[row2][col2]) {
            score++;
            printf("Congratulations, you found a matching pair!\n");
            if (score == BOARD_SIZE * BOARD_SIZE / 2) {
                game_over = 1;
                printf("You won in %d guesses!\n", num_guesses);
            }
        } else {
            // Wait for a moment to show the cards before flipping them back over
            for (int i = 0; i < 100000000; i++);
            flipped[row1][col1] = 0;
            flipped[row2][col2] = 0;
            printf("Sorry, those cards do not match.\n");
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define KEY_LENGTH 26
#define ALPHABET_SIZE 26
#define FILE_MODE "r+b"

// Function to shift characters in alphabet by a given offset
char shift_char(char c, int offset) {
    char shifted_char;
    if (isalpha(c)) {
        shifted_char = ((int)c + offset - (int)'a') % ALPHABET_SIZE + 'a';
    } else {
        shifted_char = c;
    }
    return shifted_char;
}

// Function to generate a random key using current time
void generate_key(char *key) {
    time_t t;
    struct tm *tm;
    int i;

    time(&t);
    tm = localtime(&t);

    for (i = 0; i < KEY_LENGTH; i++) {
        key[i] = shift_char('a' + (i % 5), tm->tm_sec + tm->tm_min * 60 + tm->tm_hour * 3600);
    }

    key[KEY_LENGTH] = '\0';
}

// Function to encrypt a single character
char encrypt_char(char c, char *key) {
    char encrypted_char;

    encrypted_char = shift_char(c, key[(int)c % ALPHABET_SIZE]);

    return encrypted_char;
}

// Function to encrypt a whole file
void encrypt_file(FILE *input, FILE *output, char *key) {
    char c;

    while ((c = fgetc(input)) != EOF) {
        fputc(encrypt_char(c, key), output);
    }
}

int main(int argc, char **argv) {
    FILE *input_file, *output_file;
    char *key;

    if (argc != 3) {
        printf("Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    input_file = fopen(argv[1], FILE_MODE);
    output_file = fopen(argv[2], "wb");

    if (input_file == NULL || output_file == NULL) {
        perror("Error opening file");
        return 1;
    }

    key = malloc(sizeof(char) * (KEY_LENGTH + 1));

    generate_key(key);

    encrypt_file(input_file, output_file, key);

    printf("Key: %s\n", key);

    free(key);
    fclose(input_file);
    fclose(output_file);

    return 0;
}

