#include <unistd.h>
#include <time.h>

#define MAX_REQUEST_LENGTH 1024
#define SERVER_PORT 80
#define SERVER_NAME "www.example.com"
#define QOS_INTERVAL_MS 1000

int main(int argc, char *argv[]) {
    int sock;
    struct addrinfo hints, *servinfo, *p;
    char s[MAX_REQUEST_LENGTH];
    int rv;
    int numbytes;
    struct timeval tv;
    fd_set readfds;
    int maxfd;
    int qos_interval_ms = QOS_INTERVAL_MS;
    int qos_interval_count = 0;
    int qos_interval_count_max = 10;

    FD_ZERO(&readfds);
    FD_SET(0, &readfds);
    FD_SET(sock, &readfds);
    maxfd = sock;

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(0, &readfds);
        FD_SET(sock, &readfds);
        maxfd = sock;

        if (qos_interval_count == qos_interval_count_max) {
            gettimeofday(&tv, NULL);
            tv.tv_sec += qos_interval_ms / 1000;
            tv.tv_usec += (qos_interval_ms % 1000) * 1000;
            qos_interval_count = 0;
        }

        rv = select(maxfd + 1, &readfds, NULL, NULL, &tv);

        if (rv == -1) {
            perror("select");
            exit(1);
        }

        if (FD_ISSET(0, &readfds)) {
            fgets(s, MAX_REQUEST_LENGTH, stdin);
            send(sock, s, strlen(s), 0);
        }

        if (FD_ISSET(sock, &readfds)) {
            numbytes = recv(sock, s, MAX_REQUEST_LENGTH, 0);
            if (numbytes <= 0) {
                close(sock);
                exit(1);
            }
            printf("Received response: %s\n", s);
            qos_interval_count++;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// Define the maximum number of vertices in the graph
#define MAX_VERTICES 100

typedef struct Vertex {
    int id;
    int degree;
    struct Edge *edges;
} Vertex;

typedef struct Edge {
    int weight;
    Vertex *destination;
} Edge;

// Create a new vertex with the given ID
Vertex *create_vertex(int id) {
    Vertex *vertex = malloc(sizeof(Vertex));
    vertex->id = id;
    vertex->degree = 0;
    vertex->edges = NULL;
    return vertex;
}

// Create a new edge between two vertices with the given weight
Edge *create_edge(Vertex *source, Vertex *destination, int weight) {
    Edge *edge = malloc(sizeof(Edge));
    edge->weight = weight;
    edge->destination = destination;
    return edge;
}

// Add an edge to the list of edges for a vertex
void add_edge(Vertex *vertex, Edge *edge) {
    edge->destination->degree++;
    vertex->edges = realloc(vertex->edges, sizeof(Edge) * vertex->degree);
    vertex->edges[vertex->degree - 1] = *edge;
}

// Print the graph in a readable format
void print_graph(Vertex *vertices, int num_vertices) {
    for (int i = 0; i < num_vertices; i++) {
        printf("Vertex %d: ", vertices[i].id);
        Edge *edge = vertices[i].edges;
        while (edge!= NULL) {
            printf("(%d, %d) ", edge->destination->id, edge->weight);
            edge = edge->destination->edges;
        }
        printf("\n");
    }
}

// Free the memory used by the graph
void free_graph(Vertex *vertices, int num_vertices) {
    for (int i = 0; i < num_vertices; i++) {
        Edge *edge = vertices[i].edges;
        while (edge!= NULL) {
            free(edge);
            edge = edge->destination->edges;
        }
        free(vertices[i].edges);
        free(vertices[i].id);
    }
    free(vertices);
}

int main() {
    // Create some vertices
    Vertex *a = create_vertex(1);
    Vertex *b = create_vertex(2);
    Vertex *c = create_vertex(3);
    Vertex *d = create_vertex(4);

    // Add some edges
    add_edge(a, create_edge(a, b, 3));
    add_edge(a, create_edge(a, c, 2));
    add_edge(b, create_edge(b, d, 5));
    add_edge(c, create_edge(c, d, 1));

    // Print the graph
    print_graph(a, 4);

    // Free the memory used by the graph
    free_graph(a, 4);

    return 0;
}

