    int wm_width = 4;
    int wm_height = 4;

    embed_watermark(image, watermark, wm_width, wm_height);
    write_image("output.pgm", image);
    free_image(image);

    printf("Watermark embedded and saved to 'output.pgm'\n");
    return 0;
