#include <stdio.h>
#include <stdlib.h>
#include <time.h>

struct Bidder {
    char name[20];
    int bid;
};

struct Item {
    char name[20];
    int starting_bid;
    int current_bid;
    struct Bidder highest_bidder;
};

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    // Create the auction items
    struct Item items[] = {
        {"Sword of Montague", 100, 0, {""}},
        {"Dagger of Capulet", 150, 0, {""}},
        {"Potion of Love", 200, 0, {""}}
    };

    // Get the number of bidders
    int num_bidders;
    printf("Enter the number of bidders: ");
    scanf("%d", &num_bidders);

    // Create the bidders
    struct Bidder bidders[num_bidders];
    for (int i = 0; i < num_bidders; i++) {
        printf("Enter the name of bidder %d: ", i + 1);
        scanf("%s", bidders[i].name);
    }

    // Start the auction
    for (int i = 0; i < sizeof(items) / sizeof(struct Item); i++) {
        // Display the item
        printf("Item: %s\n", items[i].name);
        printf("Starting bid: %d\n", items[i].starting_bid);

        // Get the bids
        for (int j = 0; j < num_bidders; j++) {
            int bid;
            printf("%s, enter your bid: ", bidders[j].name);
            scanf("%d", &bid);

            // Check if the bid is valid
            if (bid < items[i].starting_bid) {
                printf("Invalid bid. Please enter a bid greater than or equal to the starting bid.\n");
                j--;
                continue;
            }

            // Update the highest bid
            if (bid > items[i].current_bid) {
                items[i].current_bid = bid;
                items[i].highest_bidder = bidders[j];
            }
        }

        // Display the winner
        printf("The winner of %s is %s with a bid of %d.\n", items[i].name, items[i].highest_bidder.name, items[i].current_bid);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>

#define MAX_FILE_SIZE 1024
#define MAX_BUFFER_SIZE 256

// Structure to hold file information
struct file_info {
    char *filename;
    int file_size;
    int buffer_size;
    char *buffer;
};

// Function to open a file in read-only mode
struct file_info open_file(const char *filename) {
    int fd;
    struct file_info fi;

    // Check if the file exists
    if (access(filename, F_OK) != 0) {
        perror("Error: File does not exist");
        return fi;
    }

    // Open the file in read-only mode
    fd = open(filename, O_RDONLY, 0666);
    if (fd == -1) {
        perror("Error: Unable to open file");
        return fi;
    }

    // Get the file size
    fi.file_size = get_file_size(fd);
    if (fi.file_size == -1) {
        perror("Error: Unable to get file size");
        close(fd);
        return fi;
    }

    // Allocate memory for the buffer
    fi.buffer_size = MAX_BUFFER_SIZE;
    fi.buffer = malloc(fi.buffer_size);
    if (fi.buffer == NULL) {
        perror("Error: Unable to allocate memory for buffer");
        close(fd);
        return fi;
    }

    // Read the file into the buffer
    read(fd, fi.buffer, fi.buffer_size);
    if (read(fd, fi.buffer, fi.buffer_size) != fi.buffer_size) {
        perror("Error: Unable to read file");
        free(fi.buffer);
        close(fd);
        return fi;
    }

    // Close the file
    close(fd);

    return fi;
}

// Function to get the file size of a file
int get_file_size(int fd) {
    struct stat filestat;

    // Get the file size
    if (fstat(fd, &filestat) != 0) {
        perror("Error: Unable to get file size");
        return -1;
    }

    // Return the file size
    return filestat.st_size;
}

int main() {
    struct file_info fi = open_file("example.txt");
    if (fi.buffer == NULL) {
        perror("Error: Unable to open file");
        return 1;
    }

    // Do something with the file contents
    printf("File contents: %s\n", fi.buffer);

    // Free the buffer
    free(fi.buffer);

    return 0;
}

