#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINES 100
#define MAX_LINE_LENGTH 256

typedef struct {
    char *line;
    int significance;
} LineInfo;

int compare(const void *a, const void *b) {
    return ((LineInfo *)b)->significance - ((LineInfo *)a)->significance; 
}

int calculate_significance(const char *line) {
    int score = 0;
    char *token = strtok(strdup(line), " ");
    while (token) {
        if (strlen(token) > 4) {
            score += 2; // Longer words hold more weight
        }
        if (strchr("aeiou", token[0]) != NULL) {
            score += 1; // Start with a vowel adds weight
        }
        token = strtok(NULL, " ");
    }
    return score;
}

void extract_meaning(char **text, int count) {
    LineInfo *lineInfos = malloc(sizeof(LineInfo) * count);
    int i;

    for (i = 0; i < count; i++) {
        lineInfos[i].line = text[i];
        lineInfos[i].significance = calculate_significance(text[i]);
    }

    qsort(lineInfos, count, sizeof(LineInfo), compare);

    printf("~~ Summarized Output ~~\n");
    for (i = 0; i < count && i < 5; i++) { 
        printf("%s\n", lineInfos[i].line);
    }
    free(lineInfos);
}

int main() {
    printf("** Text Summarizer by Cryptic Minds **\n");
    char *text[MAX_LINES];
    char line[MAX_LINE_LENGTH];
    int lineCount = 0;

    printf("Input your text (type 'END' to finish):\n");

    while (lineCount < MAX_LINES) {
        fgets(line, sizeof(line), stdin);
        if (strncmp(line, "END", 3) == 0) {
            break;
        }
        text[lineCount] = strdup(line);
        lineCount++;
    }

    extract_meaning(text, lineCount);

    for (int i = 0; i < lineCount; i++) {
        free(text[i]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *name;
    char *content;
} element;

void parse_element(char *start_tag, char *end_tag, char *xml, element *elem) {
    int start_index = strstr(xml, start_tag) - xml;
    int end_index = strstr(xml, end_tag) - xml;
    int length = end_index - (start_index + strlen(start_tag));

    elem->name = start_tag + 1;
    elem->name[strlen(elem->name) - 1] = '\0';
    elem->content = (char*) malloc(length * sizeof(char));
    strncpy(elem->content, xml + start_index + strlen(start_tag), length);
    elem->content[length - 1] = '\0';
}

int main() {
    FILE *fp;
    char *xml;
    element parsed_element;

    // Open the XML file
    fp = fopen("example.xml", "r");
    if (fp == NULL) {
        printf("Error: Could not open file.\n");
        return 1;
    }

    // Calculate the file size and read the file into memory
    fseek(fp, 0, SEEK_END);
    int size = ftell(fp);
    rewind(fp);
    xml = (char*) malloc(size * sizeof(char));
    fread(xml, sizeof(char), size, fp);

    // Parse the XML file
    parse_element("<name>", "</name>", xml, &parsed_element);
    printf("Name: %s\n", parsed_element.content);

    parse_element("<age>", "</age>", xml, &parsed_element);
    printf("Age: %s\n", parsed_element.content);

    // Clean up memory and close the file
    free(xml);
    free(parsed_element.content);
    fclose(fp);

    return 0;
}

