    }

    fs->disk->data = malloc(file_size);
    if (fs->disk->data == NULL) {
        fprintf(stderr, "Error: could not allocate memory for disk data\n");
        return 1;
    }

    fs->disk->size = file_size;
    fread(fs->disk->data, 1, file_size, fp);
