        printf("Error: could not open file %s\n", filename);
        exit(1);
    }

    fseek(fp, 0, SEEK_END);
    long filesize = ftell(fp);
    rewind(fp);

    img->data = malloc(filesize);
    fread(img->data, filesize, 1, fp);
    fclose(fp);

    img->width = atoi((char*)img->data);
    img->height = atoi((char*)(img->data + 4));
