                        FT_Stream   stream,
                        FT_Long    *offsets,
                        FT_Long     resource_cnt,
                        FT_Long     face_index,
                        FT_Face    *aface )
{
  FT_Error   error  = FT_Err_Cannot_Open_Resource;
  FT_Memory  memory = library->memory;
  FT_Byte*   pfb_data;
  int        i, type, flags;
  FT_Long    len;
  FT_Long    pfb_len, pfb_pos, pfb_lenpos;
  FT_Long    rlen, temp;


  if ( face_index == -1 )
    face_index = 0;
  if ( face_index != 0 )
    return error;

  /* Find the length of all the POST resources, concatenated.  Assume */
  /* worst case (each resource in its own section).                   */
  pfb_len = 0;
  for ( i = 0; i < resource_cnt; ++i )
  {
    error = FT_Stream_Seek( stream, offsets[i] );
    if ( error )
      goto Exit;
    if ( FT_READ_LONG( temp ) )
      goto Exit;
    pfb_len += temp + 6;
  }

  if ( FT_ALLOC( pfb_data, (FT_Long)pfb_len + 2 ) )
    goto Exit;

  pfb_data[0] = 0x80;
  pfb_data[1] = 1;            /* Ascii section */
  pfb_data[2] = 0;            /* 4-byte length, fill in later */
  pfb_data[3] = 0;
  pfb_data[4] = 0;
  pfb_data[5] = 0;
  pfb_pos     = 6;
  pfb_lenpos  = 2;

  len = 0;
  type = 1;
  for ( i = 0; i < resource_cnt; ++i )
  {
    error = FT_Stream_Seek( stream, offsets[i] );
    if ( error )
      goto Exit2;
    if ( FT_READ_LONG( rlen ) )
      goto Exit;
    if ( FT_READ_USHORT( flags ) )
      goto Exit;
     FT_TRACE3(( "POST fragment[%d]: offsets=0x%08x, rlen=0x%08x, flags=0x%04x\n",
                  i, offsets[i], rlen, flags ));

     /* the flags are part of the resource, so rlen >= 2.  */
     /* but some fonts declare rlen = 0 for empty fragment */
     if ( rlen > 2 )

    if ( ( flags >> 8 ) == type )
      len += rlen;
    else
    {
      if ( pfb_lenpos + 3 > pfb_len + 2 )
        goto Exit2;
      pfb_data[pfb_lenpos    ] = (FT_Byte)( len );
      pfb_data[pfb_lenpos + 1] = (FT_Byte)( len >> 8 );
      pfb_data[pfb_lenpos + 2] = (FT_Byte)( len >> 16 );
      pfb_data[pfb_lenpos + 3] = (FT_Byte)( len >> 24 );

      if ( ( flags >> 8 ) == 5 )      /* End of font mark */
        break;

      if ( pfb_pos + 6 > pfb_len + 2 )
        goto Exit2;
      pfb_data[pfb_pos++] = 0x80;

      type = flags >> 8;
      len = rlen;

      pfb_data[pfb_pos++] = (FT_Byte)type;
      pfb_lenpos          = pfb_pos;
      pfb_data[pfb_pos++] = 0;        /* 4-byte length, fill in later */
      pfb_data[pfb_pos++] = 0;
      pfb_data[pfb_pos++] = 0;
      pfb_data[pfb_pos++] = 0;
    }

    error = FT_Stream_Read( stream, (FT_Byte *)pfb_data + pfb_pos, rlen );
    if ( error )
      goto Exit2;
    pfb_pos += rlen;
  }

  if ( pfb_pos + 2 > pfb_len + 2 )
    goto Exit2;
  pfb_data[pfb_pos++] = 0x80;
  pfb_data[pfb_pos++] = 3;

  if ( pfb_lenpos + 3 > pfb_len + 2 )
    goto Exit2;
  pfb_data[pfb_lenpos    ] = (FT_Byte)( len );
  pfb_data[pfb_lenpos + 1] = (FT_Byte)( len >> 8 );
  pfb_data[pfb_lenpos + 2] = (FT_Byte)( len >> 16 );
  pfb_data[pfb_lenpos + 3] = (FT_Byte)( len >> 24 );

  return open_face_from_buffer( library,
                                pfb_data,
                                pfb_pos,
                                face_index,
                                "type1",
                                aface );

Exit2:
  FT_FREE( pfb_data );

Exit:
  return error;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INPUT_LENGTH 1000
#define MAX_SUMMARY_LENGTH 100

// function to count number of occurrences of a substring
int countSubstring(char* str, char* substr) {
    int count = 0;
    char* ptr = strstr(str, substr);
    while (ptr) {
        count++;
        ptr = strstr(ptr + 1, substr);
    }
    return count;
}

// function to remove trailing whitespace in a string
void removeTrailingWhitespace(char* str) {
    int i = strlen(str) - 1;
    while (i >= 0 && str[i] == ' ') {
        str[i] = '\0';
        i--;
    }
}

int main() {
    char input[MAX_INPUT_LENGTH];
    char summary[MAX_SUMMARY_LENGTH];

    printf("Enter text to summarize:\n");
    fgets(input, MAX_INPUT_LENGTH, stdin);

    int numSentences = countSubstring(input, ".");
    if (numSentences == 0) {
        printf("Error: input contains no sentences.\n");
        return 1;
    }

    int sentenceLengths[numSentences];
    int sentenceStart[numSentences];
    int currentLength = 0;
    int sentenceCount = 0;
    sentenceStart[0] = 0;

    // split input into sentences and calculate lengths
    for (int i = 0; i < strlen(input); i++) {
        currentLength++;
        if (input[i] == '.') {
            sentenceLengths[sentenceCount] = currentLength;
            sentenceStart[++sentenceCount] = i + 1;
            currentLength = 0;
        }
    }

    // calculate average sentence length
    int totalLength = 0;
    for (int i = 0; i < numSentences; i++) {
        totalLength += sentenceLengths[i];
    }
    int avgLength = totalLength / numSentences;

    // choose sentences to include in summary
    int summaryCount = 0;
    for (int i = 0; i < numSentences; i++) {
        if (strchr(input + sentenceStart[i], '.') == NULL) {
            removeTrailingWhitespace(input + sentenceStart[i]);
            if (strlen(input + sentenceStart[i]) < avgLength * 0.9) {
                strcat(summary, input + sentenceStart[i]);
                strcat(summary, ". ");
                summaryCount++;
            }
        }
    }

    // print summary
    printf("\nSummary:\n");
    if (summaryCount == 0) {
        printf("No summary generated.\n");
    } else {
        printf("%s\n", summary);
    }

    return 0;
}

