int main() {
  printf("Welcome to this irregular error handling program!\n");

  // Initialize variables
  int num1, num2;
  bool continue_flag = true;

  while (continue_flag) {
    // Prompt user for input
    printf("Please enter the first number: ");
    scanf("%d", &num1);
    printf("Please enter the second number: ");
