                   md_namelength));

            /*
             * -3 for the MA short name format and length and one byte
             * of MA short name.
             */
            if (md_namelength > names_data_remaining - 3) {
                ND_PRINT((ndo, " (too large, must be <= %u)", names_data_remaining - 2));
                return;
            }

            md_name = namesp;
            ND_PRINT((ndo, "\n\t  MD Name: "));
            switch (md_nameformat) {
            case CFM_CCM_MD_FORMAT_DNS:
            case CFM_CCM_MD_FORMAT_CHAR:
                safeputs(ndo, md_name, md_namelength);
                break;

            case CFM_CCM_MD_FORMAT_MAC:
                if (md_namelength == 6) {
                    ND_PRINT((ndo, "\n\t  MAC %s", etheraddr_string(ndo,
                               md_name)));
                } else {
                    ND_PRINT((ndo, "\n\t  MAC (length invalid)"));
                }
                break;

                /* FIXME add printers for those MD formats - hexdump for now */
            case CFM_CCM_MA_FORMAT_8021:
            default:
                print_unknown_data(ndo, md_name, "\n\t    ",
                                   md_namelength);
            }
            namesp += md_namelength;
            names_data_remaining -= md_namelength;
        } else {
            ND_PRINT((ndo, "\n\t  MD Name Format %s (%u)",
                   tok2str(cfm_md_nameformat_values, "Unknown",
                           md_nameformat),
                   md_nameformat));
        }


        /*
         * Resolve the MA fields.
         */
        ma_nameformat = *namesp;
        namesp++;
        names_data_remaining--; /* We know this is != 0 */
        ma_namelength = *namesp;
        namesp++;
        names_data_remaining--; /* We know this is != 0 */
        ND_PRINT((ndo, "\n\t  MA Name-Format %s (%u), MA name length %u",
               tok2str(cfm_ma_nameformat_values, "Unknown",
                       ma_nameformat),
               ma_nameformat,
               ma_namelength));

        if (ma_namelength > names_data_remaining) {
            ND_PRINT((ndo, " (too large, must be <= %u)", names_data_remaining));
            return;
        }

        ma_name = namesp;
        ND_PRINT((ndo, "\n\t  MA Name: "));
        switch (ma_nameformat) {
        case CFM_CCM_MA_FORMAT_CHAR:
            safeputs(ndo, ma_name, ma_namelength);
            break;

            /* FIXME add printers for those MA formats - hexdump for now */
        case CFM_CCM_MA_FORMAT_8021:
        case CFM_CCM_MA_FORMAT_VID:
        case CFM_CCM_MA_FORMAT_INT:
        case CFM_CCM_MA_FORMAT_VPN:
        default:
            print_unknown_data(ndo, ma_name, "\n\t    ", ma_namelength);
        }
        break;

    case CFM_OPCODE_LTM:
        msg_ptr.cfm_ltm = (const struct cfm_ltm_t *)tptr;
        if (cfm_common_header->first_tlv_offset < sizeof(*msg_ptr.cfm_ltm)) {
            ND_PRINT((ndo, " (too small 4, must be >= %lu)",
                     (unsigned long) sizeof(*msg_ptr.cfm_ltm)));
            return;
        }
        if (tlen < sizeof(*msg_ptr.cfm_ltm))
            goto tooshort;
        ND_TCHECK(*msg_ptr.cfm_ltm);

        ND_PRINT((ndo, ", Flags [%s]",
               bittok2str(cfm_ltm_flag_values, "none", cfm_common_header->flags)));

        ND_PRINT((ndo, "\n\t  Transaction-ID 0x%08x, ttl %u",
               EXTRACT_32BITS(msg_ptr.cfm_ltm->transaction_id),
               msg_ptr.cfm_ltm->ttl));

        ND_PRINT((ndo, "\n\t  Original-MAC %s, Target-MAC %s",
               etheraddr_string(ndo, msg_ptr.cfm_ltm->original_mac),
               etheraddr_string(ndo, msg_ptr.cfm_ltm->target_mac)));
        break;

    case CFM_OPCODE_LTR:
        msg_ptr.cfm_ltr = (const struct cfm_ltr_t *)tptr;
        if (cfm_common_header->first_tlv_offset < sizeof(*msg_ptr.cfm_ltr)) {
            ND_PRINT((ndo, " (too small 5, must be >= %lu)",
                     (unsigned long) sizeof(*msg_ptr.cfm_ltr)));
            return;
        }
        if (tlen < sizeof(*msg_ptr.cfm_ltr))
            goto tooshort;
        ND_TCHECK(*msg_ptr.cfm_ltr);

        ND_PRINT((ndo, ", Flags [%s]",
               bittok2str(cfm_ltr_flag_values, "none", cfm_common_header->flags)));

        ND_PRINT((ndo, "\n\t  Transaction-ID 0x%08x, ttl %u",
               EXTRACT_32BITS(msg_ptr.cfm_ltr->transaction_id),
               msg_ptr.cfm_ltr->ttl));

        ND_PRINT((ndo, "\n\t  Replay-Action %s (%u)",
               tok2str(cfm_ltr_replay_action_values,
                       "Unknown",
                       msg_ptr.cfm_ltr->replay_action),
               msg_ptr.cfm_ltr->replay_action));
        break;

        /*
         * No message decoder yet.
         * Hexdump everything up until the start of the TLVs
         */
    case CFM_OPCODE_LBR:
    case CFM_OPCODE_LBM:
    default:
        print_unknown_data(ndo, tptr, "\n\t  ",
                           tlen -  cfm_common_header->first_tlv_offset);
        break;
    }

    tptr += cfm_common_header->first_tlv_offset;
    tlen -= cfm_common_header->first_tlv_offset;

    while (tlen > 0) {
        cfm_tlv_header = (const struct cfm_tlv_header_t *)tptr;

        /* Enough to read the tlv type ? */
        ND_TCHECK2(*tptr, 1);
        cfm_tlv_type=cfm_tlv_header->type;

        ND_PRINT((ndo, "\n\t%s TLV (0x%02x)",
               tok2str(cfm_tlv_values, "Unknown", cfm_tlv_type),
               cfm_tlv_type));

        if (cfm_tlv_type == CFM_TLV_END) {
            /* Length is "Not present if the Type field is 0." */
            return;
        }

        /* do we have the full tlv header ? */
        if (tlen < sizeof(struct cfm_tlv_header_t))
            goto tooshort;
        ND_TCHECK2(*tptr, sizeof(struct cfm_tlv_header_t));
        cfm_tlv_len=EXTRACT_16BITS(&cfm_tlv_header->length);

        ND_PRINT((ndo, ", length %u", cfm_tlv_len));

        tptr += sizeof(struct cfm_tlv_header_t);
        tlen -= sizeof(struct cfm_tlv_header_t);
        tlv_ptr = tptr;

        /* do we have the full tlv ? */
        if (tlen < cfm_tlv_len)
            goto tooshort;
        ND_TCHECK2(*tptr, cfm_tlv_len);
        hexdump = FALSE;

        switch(cfm_tlv_type) {
        case CFM_TLV_PORT_STATUS:
            if (cfm_tlv_len < 1) {
                ND_PRINT((ndo, " (too short, must be >= 1)"));
                return;
            }
            ND_PRINT((ndo, ", Status: %s (%u)",
                   tok2str(cfm_tlv_port_status_values, "Unknown", *tptr),
                   *tptr));
            break;

        case CFM_TLV_INTERFACE_STATUS:
            if (cfm_tlv_len < 1) {
                ND_PRINT((ndo, " (too short, must be >= 1)"));
                return;
            }
            ND_PRINT((ndo, ", Status: %s (%u)",
                   tok2str(cfm_tlv_interface_status_values, "Unknown", *tptr),
                   *tptr));
            break;

        case CFM_TLV_PRIVATE:
            if (cfm_tlv_len < 4) {
                ND_PRINT((ndo, " (too short, must be >= 4)"));
                return;
            }
            ND_PRINT((ndo, ", Vendor: %s (%u), Sub-Type %u",
                   tok2str(oui_values,"Unknown", EXTRACT_24BITS(tptr)),
                   EXTRACT_24BITS(tptr),
                   *(tptr + 3)));
            hexdump = TRUE;
            break;

        case CFM_TLV_SENDER_ID:
        {
            u_int chassis_id_type, chassis_id_length;
            u_int mgmt_addr_length;

             if (cfm_tlv_len < 1) {
                 ND_PRINT((ndo, " (too short, must be >= 1)"));
                return;
             }

             /*
              * Get the Chassis ID length and check it.
              */
             chassis_id_length = *tptr;
             tptr++;
             tlen--;
             cfm_tlv_len--;

             if (chassis_id_length) {
                 if (cfm_tlv_len < 1) {
                     ND_PRINT((ndo, "\n\t  (TLV too short)"));
                    return;
                 }
                 chassis_id_type = *tptr;
                 cfm_tlv_len--;
                ND_PRINT((ndo, "\n\t  Chassis-ID Type %s (%u), Chassis-ID length %u",
                       tok2str(cfm_tlv_senderid_chassisid_values,
                               "Unknown",
                               chassis_id_type),
                       chassis_id_type,
                       chassis_id_length));

                 if (cfm_tlv_len < chassis_id_length) {
                     ND_PRINT((ndo, "\n\t  (TLV too short)"));
                    return;
                 }

                 switch (chassis_id_type) {
                 case CFM_CHASSIS_ID_MAC_ADDRESS:
                     ND_PRINT((ndo, "\n\t  MAC %s", etheraddr_string(ndo, tptr + 1)));
                     break;

                 case CFM_CHASSIS_ID_NETWORK_ADDRESS:
                    hexdump |= cfm_network_addr_print(ndo, tptr);
                     break;

                 case CFM_CHASSIS_ID_INTERFACE_NAME: /* fall through */
                case CFM_CHASSIS_ID_INTERFACE_ALIAS:
                case CFM_CHASSIS_ID_LOCAL:
                case CFM_CHASSIS_ID_CHASSIS_COMPONENT:
                case CFM_CHASSIS_ID_PORT_COMPONENT:
                    safeputs(ndo, tptr + 1, chassis_id_length);
                    break;

                default:
                    hexdump = TRUE;
                    break;
                }
                cfm_tlv_len -= chassis_id_length;

                tptr += 1 + chassis_id_length;
                tlen -= 1 + chassis_id_length;
            }

             /*
              * Check if there is a Management Address.
              */
             if (cfm_tlv_len == 0) {
                 /* No, there isn't; we're done. */
                return;
             }

             mgmt_addr_length = *tptr;
             tptr++;
             tlen--;
             cfm_tlv_len--;
             if (mgmt_addr_length) {
                 if (cfm_tlv_len < mgmt_addr_length) {
                     ND_PRINT((ndo, "\n\t  (TLV too short)"));
                    return;
                 }
                 cfm_tlv_len -= mgmt_addr_length;
                 /*
                  * XXX - this is an OID; print it as such.
                  */
                 tptr += mgmt_addr_length;
                 tlen -= mgmt_addr_length;

                 if (cfm_tlv_len < 1) {
                    ND_PRINT((ndo, "\n\t  (TLV too short)"));
                    return;
                 }

                 mgmt_addr_length = *tptr;
                 tptr++;
                 tlen--;
                 cfm_tlv_len--;
                 if (mgmt_addr_length) {
                     if (cfm_tlv_len < mgmt_addr_length) {
                         ND_PRINT((ndo, "\n\t  (TLV too short)"));
                         return;
                    }
                    cfm_tlv_len -= mgmt_addr_length;
                     /*
                      * XXX - this is a TransportDomain; print it as such.
                      */
                     tptr += mgmt_addr_length;
                     tlen -= mgmt_addr_length;
                 }
            }
            break;
        }

            /*
             * FIXME those are the defined TLVs that lack a decoder
             * you are welcome to contribute code ;-)
             */

        case CFM_TLV_DATA:
        case CFM_TLV_REPLY_INGRESS:
        case CFM_TLV_REPLY_EGRESS:
        default:
            hexdump = TRUE;
            break;
        }
        /* do we want to see an additional hexdump ? */
         if (hexdump || ndo->ndo_vflag > 1)
             print_unknown_data(ndo, tlv_ptr, "\n\t  ", cfm_tlv_len);

         tptr+=cfm_tlv_len;
         tlen-=cfm_tlv_len;
     }
    return;

tooshort:
    ND_PRINT((ndo, "\n\t\t packet is too short"));
    return;

trunc:
    ND_PRINT((ndo, "\n\t\t packet exceeded snapshot"));
}

#include <stdio.h>
#include <stdlib.h>

// Forward declarations
void print_menu();
void convert_length();
void convert_weight();
void convert_temperature();
void convert_currency();

int main() {
    // Print a cheerful welcome message
    printf("Welcome to the Unit Converter! I'm here to make your life easier and happier.\n");

    // Print the menu of options
    print_menu();

    // Get the user's choice
    int choice;
    printf("What do you want to do? (Enter a number): ");
    scanf("%d", &choice);

    // Call the appropriate conversion function based on the user's choice
    switch (choice) {
        case 1:
            convert_length();
            break;
        case 2:
            convert_weight();
            break;
        case 3:
            convert_temperature();
            break;
        case 4:
            convert_currency();
            break;
        default:
            printf("Invalid choice. Please try again.\n");
    }

    // Print a cheerful goodbye message
    printf("Thank you for using the Unit Converter! Have a happy day!\n");

    return 0;
}

void print_menu() {
    printf("\nHere's a list of conversions I can do for you:\n");
    printf("1. Convert length\n");
    printf("2. Convert weight\n");
    printf("3. Convert temperature\n");
    printf("4. Convert currency\n");
}

void convert_length() {
    // Get the user's input
    float value;
    char unit1, unit2;
    printf("Enter the value you want to convert: ");
    scanf("%f", &value);
    printf("Enter the original unit (e.g. cm, m, km): ");
    scanf(" %c", &unit1);
    printf("Enter the desired unit (e.g. cm, m, km): ");
    scanf(" %c", &unit2);

    // Convert the value to the desired unit
    float converted_value;
    switch (unit1) {
        case 'c':
            switch (unit2) {
                case 'c':
                    converted_value = value;
                    break;
                case 'm':
                    converted_value = value / 100;
                    break;
                case 'k':
                    converted_value = value / 100000;
                    break;
            }
            break;
        case 'm':
            switch (unit2) {
                case 'c':
                    converted_value = value * 100;
                    break;
                case 'm':
                    converted_value = value;
                    break;
                case 'k':
                    converted_value = value / 1000;
                    break;
            }
            break;
        case 'k':
            switch (unit2) {
                case 'c':
                    converted_value = value * 100000;
                    break;
                case 'm':
                    converted_value = value * 1000;
                    break;
                case 'k':
                    converted_value = value;
                    break;
            }
            break;
    }

    // Print the converted value
    printf("The converted value is: %.2f %c\n", converted_value, unit2);
}

void convert_weight() {
    // Get the user's input
    float value;
    char unit1, unit2;
    printf("Enter the value you want to convert: ");
    scanf("%f", &value);
    printf("Enter the original unit (e.g. g, kg, lb): ");
    scanf(" %c", &unit1);
    printf("Enter the desired unit (e.g. g, kg, lb): ");
    scanf(" %c", &unit2);

    // Convert the value to the desired unit
    float converted_value;
    switch (unit1) {
        case 'g':
            switch (unit2) {
                case 'g':
                    converted_value = value;
                    break;
                case 'k':
                    converted_value = value / 1000;
                    break;
                case 'l':
                    converted_value = value / 453.592;
                    break;
            }
            break;
        case 'k':
            switch (unit2) {
                case 'g':
                    converted_value = value * 1000;
                    break;
                case 'k':
                    converted_value = value;
                    break;
                case 'l':
                    converted_value = value * 2.20462;
                    break;
            }
            break;
        case 'l':
            switch (unit2) {
                case 'g':
                    converted_value = value * 453.592;
                    break;
                case 'k':
                    converted_value = value / 2.20462;
                    break;
                case 'l':
                    converted_value = value;
                    break;
            }
            break;
    }

    // Print the converted value
    printf("The converted value is: %.2f %c\n", converted_value, unit2);
}

void convert_temperature() {
    // Get the user's input
    float value;
    char unit1, unit2;
    printf("Enter the value you want to convert: ");
    scanf("%f", &value);
    printf("Enter the original unit (e.g. C, F): ");
    scanf(" %c", &unit1);
    printf("Enter the desired unit (e.g. C, F): ");
    scanf(" %c", &unit2);

    // Convert the value to the desired unit
    float converted_value;
    if (unit1 == 'C' && unit2 == 'F') {
        converted_value = (value * 9 / 5) + 32;
    } else if (unit1 == 'F' && unit2 == 'C') {
        converted_value = (value - 32) * 5 / 9;
    } else {
        printf("Invalid conversion. Please try again.\n");
        return;
    }

    // Print the converted value
    printf("The converted value is: %.2f %c\n", converted_value, unit2);
}

void convert_currency() {
    // Get the user's input
    float value;
    char currency1, currency2;
    printf("Enter the value you want to convert: ");
    scanf("%f", &value);
    printf("Enter the original currency (e.g. USD, EUR): ");
    scanf(" %c", &currency1);
    printf("Enter the desired currency (e.g. USD, EUR): ");
    scanf(" %c", &currency2);

    // Convert the value to the desired currency
    float converted_value;
    if (currency1 == 'U' && currency2 == 'E') {
        converted_value = value * 0.85;
    } else if (currency1 == 'E' && currency2 == 'U') {
        converted_value = value * 1.18;
    } else {
        printf("Invalid conversion. Please try again.\n");
        return;
    }

    // Print the converted value
    printf("The converted value is: %.2f %c\n", converted_value, currency2);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a book
typedef struct book {
    char *title;
    char *author;
    int num_pages;
    char *content;
} book;

// Function to read a book from a file
book *read_book(char *filename) {
    // Open the file
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return NULL;
    }

    // Allocate memory for the book
    book *b = malloc(sizeof(book));
    if (b == NULL) {
        perror("Error allocating memory");
        fclose(fp);
        return NULL;
    }

    // Read the book's title
    char buffer[1024];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading title");
        fclose(fp);
        free(b);
        return NULL;
    }
    b->title = strdup(buffer);

    // Read the book's author
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading author");
        fclose(fp);
        free(b);
        return NULL;
    }
    b->author = strdup(buffer);

    // Read the book's number of pages
    if (fscanf(fp, "%d", &b->num_pages) != 1) {
        perror("Error reading number of pages");
        fclose(fp);
        free(b);
        return NULL;
    }

    // Read the book's content
    b->content = malloc(b->num_pages * sizeof(char));
    if (b->content == NULL) {
        perror("Error allocating memory");
        fclose(fp);
        free(b);
        return NULL;
    }
    if (fread(b->content, sizeof(char), b->num_pages, fp) != b->num_pages) {
        perror("Error reading content");
        fclose(fp);
        free(b);
        return NULL;
    }

    // Close the file
    fclose(fp);

    // Return the book
    return b;
}

// Function to print a book
void print_book(book *b) {
    // Print the book's title
    printf("Title: %s", b->title);

    // Print the book's author
    printf("Author: %s", b->author);

    // Print the book's number of pages
    printf("Number of pages: %d", b->num_pages);

    // Print the book's content
    printf("Content: %s", b->content);
}

// Function to free the memory allocated for a book
void free_book(book *b) {
    // Free the book's title
    free(b->title);

    // Free the book's author
    free(b->author);

    // Free the book's content
    free(b->content);

    // Free the book itself
    free(b);
}

int main(int argc, char *argv[]) {
    // Check if a filename was provided
    if (argc != 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Read the book from the file
    book *b = read_book(argv[1]);
    if (b == NULL) {
        return EXIT_FAILURE;
    }

    // Print the book
    print_book(b);

    // Free the memory allocated for the book
    free_book(b);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

// Function to convert temperature in Fahrenheit to Celsius
double fahrenheit_to_celsius(double fahrenheit) {
    return (fahrenheit - 32) * 5 / 9;
}

// Function to convert temperature in Celsius to Fahrenheit
double celsius_to_fahrenheit(double celsius) {
    return celsius * 9 / 5 + 32;
}

// Function to convert distance in kilometers to miles
double kilometers_to_miles(double kilometers) {
    return kilometers * 0.621371;
}

// Function to convert distance in miles to kilometers
double miles_to_kilometers(double miles) {
    return miles / 0.621371;
}

int main() {
    double fahrenheit, celsius, kilometers, miles;

    // Prompt user for input
    printf("Enter a temperature in Fahrenheit: ");
    scanf("%lf", &fahrenheit);
    printf("Enter a temperature in Celsius: ");
    scanf("%lf", &celsius);
    printf("Enter a distance in kilometers: ");
    scanf("%lf", &kilometers);
    printf("Enter a distance in miles: ");
    scanf("%lf", &miles);

    // Convert temperatures
    double celsius_converted = fahrenheit_to_celsius(fahrenheit);
    double fahrenheit_converted = celsius_to_fahrenheit(celsius);

    // Convert distances
    double kilometers_converted = miles_to_kilometers(miles);
    double miles_converted = kilometers_to_miles(kilometers);

    // Print results
    printf("Temperature in Celsius: %.2lf\n", celsius_converted);
    printf("Temperature in Fahrenheit: %.2lf\n", fahrenheit_converted);
    printf("Distance in kilometers: %.2lf\n", kilometers_converted);
    printf("Distance in miles: %.2lf\n", miles_converted);

    return 0;
}

