    SDHCIState *s = (SDHCIState *)opaque;
    unsigned shift =  8 * (offset & 0x3);
    uint32_t mask = ~(((1ULL << (size * 8)) - 1) << shift);
    uint32_t value = val;
    value <<= shift;

    switch (offset & ~0x3) {
    case SDHC_SYSAD:
        s->sdmasysad = (s->sdmasysad & mask) | value;
        MASKED_WRITE(s->sdmasysad, mask, value);
        /* Writing to last byte of sdmasysad might trigger transfer */
        if (!(mask & 0xFF000000) && TRANSFERRING_DATA(s->prnsts) && s->blkcnt &&
                s->blksize && SDHC_DMA_TYPE(s->hostctl1) == SDHC_CTRL_SDMA) {
            if (s->trnmod & SDHC_TRNS_MULTI) {
                sdhci_sdma_transfer_multi_blocks(s);
            } else {
                sdhci_sdma_transfer_single_block(s);
            }
        }
        break;
    case SDHC_BLKSIZE:
        if (!TRANSFERRING_DATA(s->prnsts)) {
            MASKED_WRITE(s->blksize, mask, extract32(value, 0, 12));
            MASKED_WRITE(s->blkcnt, mask >> 16, value >> 16);
        }

        /* Limit block size to the maximum buffer size */
        if (extract32(s->blksize, 0, 12) > s->buf_maxsz) {
            qemu_log_mask(LOG_GUEST_ERROR, "%s: Size 0x%x is larger than "
                          "the maximum buffer 0x%x\n", __func__, s->blksize,
                          s->buf_maxsz);

            s->blksize = deposit32(s->blksize, 0, 12, s->buf_maxsz);
        }

        break;
    case SDHC_ARGUMENT:
        MASKED_WRITE(s->argument, mask, value);
        break;
    case SDHC_TRNMOD:
        /* DMA can be enabled only if it is supported as indicated by
         * capabilities register */
        if (!(s->capareg & R_SDHC_CAPAB_SDMA_MASK)) {
            value &= ~SDHC_TRNS_DMA;
        }
        MASKED_WRITE(s->trnmod, mask, value & SDHC_TRNMOD_MASK);
        MASKED_WRITE(s->cmdreg, mask >> 16, value >> 16);

        /* Writing to the upper byte of CMDREG triggers SD command generation */
        if ((mask & 0xFF000000) || !sdhci_can_issue_command(s)) {
            break;
        }

        sdhci_send_command(s);
        break;
    case  SDHC_BDATA:
        if (sdhci_buff_access_is_sequential(s, offset - SDHC_BDATA)) {
            sdhci_write_dataport(s, value >> shift, size);
        }
        break;
    case SDHC_HOSTCTL:
        if (!(mask & 0xFF0000)) {
            sdhci_blkgap_write(s, value >> 16);
        }
        MASKED_WRITE(s->hostctl1, mask, value);
        MASKED_WRITE(s->pwrcon, mask >> 8, value >> 8);
        MASKED_WRITE(s->wakcon, mask >> 24, value >> 24);
        if (!(s->prnsts & SDHC_CARD_PRESENT) || ((s->pwrcon >> 1) & 0x7) < 5 ||
                !(s->capareg & (1 << (31 - ((s->pwrcon >> 1) & 0x7))))) {
            s->pwrcon &= ~SDHC_POWER_ON;
        }
        break;
    case SDHC_CLKCON:
        if (!(mask & 0xFF000000)) {
            sdhci_reset_write(s, value >> 24);
        }
        MASKED_WRITE(s->clkcon, mask, value);
        MASKED_WRITE(s->timeoutcon, mask >> 16, value >> 16);
        if (s->clkcon & SDHC_CLOCK_INT_EN) {
            s->clkcon |= SDHC_CLOCK_INT_STABLE;
        } else {
            s->clkcon &= ~SDHC_CLOCK_INT_STABLE;
        }
        break;
    case SDHC_NORINTSTS:
        if (s->norintstsen & SDHC_NISEN_CARDINT) {
            value &= ~SDHC_NIS_CARDINT;
        }
        s->norintsts &= mask | ~value;
        s->errintsts &= (mask >> 16) | ~(value >> 16);
        if (s->errintsts) {
            s->norintsts |= SDHC_NIS_ERR;
        } else {
            s->norintsts &= ~SDHC_NIS_ERR;
        }
        sdhci_update_irq(s);
        break;
    case SDHC_NORINTSTSEN:
        MASKED_WRITE(s->norintstsen, mask, value);
        MASKED_WRITE(s->errintstsen, mask >> 16, value >> 16);
        s->norintsts &= s->norintstsen;
        s->errintsts &= s->errintstsen;
        if (s->errintsts) {
            s->norintsts |= SDHC_NIS_ERR;
        } else {
            s->norintsts &= ~SDHC_NIS_ERR;
        }
        /* Quirk for Raspberry Pi: pending card insert interrupt
         * appears when first enabled after power on */
        if ((s->norintstsen & SDHC_NISEN_INSERT) && s->pending_insert_state) {
            assert(s->pending_insert_quirk);
            s->norintsts |= SDHC_NIS_INSERT;
            s->pending_insert_state = false;
        }
        sdhci_update_irq(s);
        break;
    case SDHC_NORINTSIGEN:
        MASKED_WRITE(s->norintsigen, mask, value);
        MASKED_WRITE(s->errintsigen, mask >> 16, value >> 16);
        sdhci_update_irq(s);
        break;
    case SDHC_ADMAERR:
        MASKED_WRITE(s->admaerr, mask, value);
        break;
    case SDHC_ADMASYSADDR:
        s->admasysaddr = (s->admasysaddr & (0xFFFFFFFF00000000ULL |
                (uint64_t)mask)) | (uint64_t)value;
        break;
    case SDHC_ADMASYSADDR + 4:
        s->admasysaddr = (s->admasysaddr & (0x00000000FFFFFFFFULL |
                ((uint64_t)mask << 32))) | ((uint64_t)value << 32);
        break;
    case SDHC_FEAER:
        s->acmd12errsts |= value;
        s->errintsts |= (value >> 16) & s->errintstsen;
        if (s->acmd12errsts) {
            s->errintsts |= SDHC_EIS_CMD12ERR;
        }
        if (s->errintsts) {
            s->norintsts |= SDHC_NIS_ERR;
        }
        sdhci_update_irq(s);
        break;
    case SDHC_ACMD12ERRSTS:
        MASKED_WRITE(s->acmd12errsts, mask, value & UINT16_MAX);
        if (s->uhs_mode >= UHS_I) {
            MASKED_WRITE(s->hostctl2, mask >> 16, value >> 16);

            if (FIELD_EX32(s->hostctl2, SDHC_HOSTCTL2, V18_ENA)) {
                sdbus_set_voltage(&s->sdbus, SD_VOLTAGE_1_8V);
            } else {
                sdbus_set_voltage(&s->sdbus, SD_VOLTAGE_3_3V);
            }
        }
        break;

    case SDHC_CAPAB:
    case SDHC_CAPAB + 4:
    case SDHC_MAXCURR:
    case SDHC_MAXCURR + 4:
        qemu_log_mask(LOG_GUEST_ERROR, "SDHC wr_%ub @0x%02" HWADDR_PRIx
                      " <- 0x%08x read-only\n", size, offset, value >> shift);
        break;

    default:
        qemu_log_mask(LOG_UNIMP, "SDHC wr_%ub @0x%02" HWADDR_PRIx " <- 0x%08x "
                      "not implemented\n", size, offset, value >> shift);
        break;
    }
    trace_sdhci_access("wr", size << 3, offset, "<-",
                       value >> shift, value >> shift);
}

#include <stdio.h>
#include <stdlib.h>

#define SIZE 8

char board[SIZE][SIZE];

void initialize_board() {
    // Initialize empty board
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            board[i][j] = ' ';
        }
    }
    // Place pieces for Player 1
    for (int i = 0; i < 3; i++) {
        for (int j = (i % 2); j < SIZE; j += 2) {
            board[i][j] = 'A'; // Player 1's pieces
        }
    }
    // Place pieces for Player 2
    for (int i = 5; i < 8; i++) {
        for (int j = (i % 2); j < SIZE; j += 2) {
            board[i][j] = 'B'; // Player 2's pieces
        }
    }
}

void display_board() {
    printf("   a b c d e f g h\n");
    for (int i = 0; i < SIZE; i++) {
        printf("%d ", SIZE - i);
        for (int j = 0; j < SIZE; j++) {
            printf("%c ", board[i][j]);
        }
        printf("\n");
    }
}

int is_valid_move(int from_row, int from_col, int to_row, int to_col, char player) {
    // Check if destination is within bounds and empty
    if (to_row < 0 || to_row >= SIZE || to_col < 0 || to_col >= SIZE || board[to_row][to_col] != ' ') {
        return 0;
    }
    // Check jumping rules for captures
    if (abs(to_row - from_row) == 2 && abs(to_col - from_col) == 2) {
        int mid_row = (from_row + to_row) / 2;
        int mid_col = (from_col + to_col) / 2;
        if (board[mid_row][mid_col] != ' ' && board[mid_row][mid_col] != player) {
            return 1; // Valid jump
        }
    }
    // Check normal move rules
    if (abs(to_row - from_row) == 1 && abs(to_col - from_col) == 1) {
        return player == 'A' ? to_row > from_row : to_row < from_row; // Directional move
    }
    return 0;
}

void move_piece(int from_row, int from_col, int to_row, int to_col) {
    char player = board[from_row][from_col];
    board[to_row][to_col] = player;
    board[from_row][from_col] = ' ';
    if (abs(to_row - from_row) == 2) {
        int mid_row = (from_row + to_row) / 2;
        int mid_col = (from_col + to_col) / 2;
        board[mid_row][mid_col] = ' '; // Remove captured piece
    }
}

int main() {
    initialize_board();
    display_board();

    int from_row, from_col, to_row, to_col;
    char from_col_char, to_col_char;
    char current_player = 'A'; // Starting with Player 1 'A'

    while (1) {
        printf("Player %c's turn. Enter move (e.g., 'a3 b4'): ", current_player);
        scanf(" %c%d %c%d", &from_col_char, &from_row, &to_col_char, &to_row);

        from_col = from_col_char - 'a';
        to_col = to_col_char - 'a';
        from_row = SIZE - from_row;
        to_row = SIZE - to_row;

        if (from_row < 0 || from_row >= SIZE || from_col < 0 || from_col >= SIZE ||
            to_row < 0 || to_row >= SIZE || to_col < 0 || to_col >= SIZE ||
            board[from_row][from_col] != current_player) {
            printf("Invalid move! Try again.\n");
            continue;
        }

        if (is_valid_move(from_row, from_col, to_row, to_col, current_player)) {
            move_piece(from_row, from_col, to_row, to_col);
            display_board();
            current_player = (current_player == 'A') ? 'B' : 'A'; // Switch player
        } else {
            printf("Invalid move! Try again.\n");
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_FLOOR 10
#define MIN_FLOOR 1
#define ELEVATOR_CAPACITY 10
#define DOOR_OPEN_TIME 5

typedef struct {
    int floor;
    bool isDoorOpen;
    int numPeopleInside;
} Elevator;

void initializeElevator(Elevator *elevator);
bool isElevatorFull(Elevator *elevator);
void openDoor(Elevator *elevator);
void closeDoor(Elevator *elevator);
void goToFloor(Elevator *elevator, int floor);
void printElevatorStatus(Elevator *elevator);

int main() {
    srand(time(NULL)); // Seed random number generator with current time

    Elevator elevator;
    initializeElevator(&elevator);

    for (int i = 1; i <= 20; i++) { // Loop 20 times to simulate moving between floors
        printf("Elevator is on floor %d\n", elevator.floor);

        if (elevator.isDoorOpen) {
            elevator.isDoorOpen = false; // Close door if it's open
            printf("Door closed\n");
        }

        int numPeopleToEnter = rand() % (ELEVATOR_CAPACITY - elevator.numPeopleInside) + 1;
        elevator.numPeopleInside += numPeopleToEnter;
        printf("%d people entered the elevator\n", numPeopleToEnter);

        int numPeopleToExit = rand() % (elevator.numPeopleInside + 1);
        elevator.numPeopleInside -= numPeopleToExit;
        printf("%d people exited the elevator\n", numPeopleToExit);

        int destinationFloor = rand() % MAX_FLOOR + 1;
        goToFloor(&elevator, destinationFloor);

        openDoor(&elevator);
        printf("Door opened\n");

        printf("Waiting for passengers...\n");
        sleep(DOOR_OPEN_TIME);
    }

    return 0;
}

void initializeElevator(Elevator *elevator) {
    elevator->floor = MIN_FLOOR;
    elevator->isDoorOpen = false;
    elevator->numPeopleInside = 0;
}

bool isElevatorFull(Elevator *elevator) {
    return elevator->numPeopleInside == ELEVATOR_CAPACITY;
}

void openDoor(Elevator *elevator) {
    elevator->isDoorOpen = true;
}

void closeDoor(Elevator *elevator) {
    elevator->isDoorOpen = false;
}

void goToFloor(Elevator *elevator, int floor) {
    int direction = (floor > elevator->floor) ? 1 : -1;

    while (elevator->floor != floor) {
        elevator->floor += direction;
        printElevatorStatus(elevator);
        sleep(1); // Pause for 1 second to simulate time passing
    }
}

void printElevatorStatus(Elevator *elevator) {
    printf("Elevator is on floor %d with %d people inside\n", elevator->floor, elevator->numPeopleInside);
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAP_WIDTH 50
#define MAP_HEIGHT 20

#define invader_WIDTH 10
#define invader_HEIGHT 2

#define BULLET_WIDTH 2
#define BULLET_HEIGHT 2

#define PLAYER_WIDTH 2
#define PLAYER_HEIGHT 2

#define PLAYER_SPEED 5
#define BULLET_SPEED 10

// Define the invader movement pattern
#define invader_MOVEMENT_PATTERN_WIDTH 5
#define invader_MOVEMENT_PATTERN_HEIGHT 3

// Define the invader bullet pattern
#define invader_BULLET_PATTERN_WIDTH 3
#define invader_BULLET_PATTERN_HEIGHT 2

// Define the player bullet pattern
#define PLAYER_BULLET_PATTERN_WIDTH 3
#define PLAYER_BULLET_PATTERN_HEIGHT 2

int main()
{
  // Initialize the game map
  int map[MAP_HEIGHT][MAP_WIDTH] = {{0}};

  // Initialize the invader
  int invader_x = 0;
  int invader_y = 0;
  int invader_direction = 1;

  // Initialize the player
  int player_x = MAP_WIDTH / 2;
  int player_y = MAP_HEIGHT - 1;

  // Initialize the bullets
  int bullet_x[10] = {0};
  int bullet_y[10] = {0};
  int bullet_direction[10] = {0};

  // Initialize the clock
  time_t start_time = time(NULL);
  time_t end_time = time(NULL);

  // Game loop
  while (!map[invader_y][invader_x])
  {
    // Update the clock
    start_time = time(NULL);

    // Move the invader
    invader_x += invader_direction * PLAYER_SPEED * (time(NULL) - start_time) / 100;

    // Check if the invader has reached the edge of the map
    if (invader_x < 0 || invader_x >= MAP_WIDTH)
    {
      invader_direction *= -1;
    }

    // Move the player
    player_x += PLAYER_SPEED * (time(NULL) - start_time) / 100;

    // Check if the player has reached the edge of the map
    if (player_x < 0 || player_x >= MAP_WIDTH)
    {
      // Game over
      break;
    }

    // Fire a bullet
    if (time(NULL) - start_time > 5)
    {
      bullet_x[0] = player_x;
      bullet_y[0] = player_y;
      bullet_direction[0] = -invader_direction;
      start_time = time(NULL);
    }

    // Update the bullets
    for (int i = 0; i < 10; i++)
    {
      bullet_x[i] += bullet_direction[i] * BULLET_SPEED * (time(NULL) - start_time) / 100;
      bullet_y[i] -= BULLET_SPEED * (time(NULL) - start_time) / 100;

      // Check if the bullet has reached the invader
      if (bullet_x[i] >= invader_x && bullet_x[i] <= invader_x + invader_WIDTH && bullet_y[i] >= invader_y && bullet_y[i] <= invader_y + invader_HEIGHT)
      {
        map[invader_y][invader_x] = 1;
        bullet_x[i] = -1;
        bullet_y[i] = -1;
      }
    }

    // Draw the map
    for (int y = 0; y < MAP_HEIGHT; y++)
    {
      for (int x = 0; x < MAP_WIDTH; x++)
      {
        if (map[y][x] == 1)
        {
          printf("#");
        }
        else
        {
          printf(" ");
        }
      }
      printf("\n");
    }

    // Draw the invader
    printf("o");

    // Draw the player
    printf("x");

    // Draw the bullets
    for (int i = 0; i < 10; i++)
    {
      if (bullet_x[i] >= 0 && bullet_x[i] < MAP_WIDTH && bullet_y[i] >= 0)
      {
        printf("o");
      }
    }

    // Update the clock
    end_time = time(NULL);
  }

  // Game over
  printf("Game over!");

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* This program demonstrates a basic example of digital watermarking using C language. */
/* It takes an input image file and embeds a secret message as a watermark using LSB algorithm. */ 

/*-------------------------------- Functions --------------------------------*/

/* function to embed watermark message into image */
void embedMessage(FILE *image, FILE *watermark, FILE *output, char message[])
{
    int ch, bit;
    char *msg = message;
    while (*msg)
    {
        ch = *msg;
        for (int i = 0; i < 8; i++)
        {
            bit = (ch & (1 << i)) ? 1 : 0;
            if (fread(&ch, 1, 1, image) == 0) /* if image has ended, exit the loop */
                return;
            ch = (ch & 0xFE) | bit; /* set last bit to message bit */
            fwrite(&ch, 1, 1, output);
        }
        msg++;
    }

    /* copy remaining data from image to output file */
    while (fread(&ch, 1, 1, image))
    {
        fwrite(&ch, 1, 1, output);
    }

    printf("Watermark embedded successfully!");
}

/* function to extract and print watermark message from image */
void extractMessage(FILE *image)
{
    char message[256];
    int ch, bit, count = 0;
    while (1)
    {
        ch = 0;
        for (int i = 0; i < 8; i++)
        {
            if (fread(&bit, 1, 1, image) == 0) /* if image has ended, exit the loop */
                goto Exit;
            ch |= bit << i; /* extract message bit from image byte */
        }
        if (ch == '\0') /* if end of message, exit the loop */
            break;
        message[count++] = ch;
    }
    message[count] = '\0';
    printf("The extracted message is: %s", message);

Exit:
    printf("\nWatermark extracted successfully!");
}

/*-------------------------------- Main --------------------------------*/

int main()
{
    FILE *image, *watermark, *output;
    char filename[50], message[256];

    printf("\nEnter the name of the image file: ");
    scanf("%s", filename);
    image = fopen(filename, "rb");
    if (image == NULL)
    {
        printf("Unable to open image file!");
        exit(1);
    }

    printf("Enter the name of the file containing watermark message: ");
    scanf("%s", filename);
    watermark = fopen(filename, "r");
    if (watermark == NULL)
    {
        printf("Unable to open watermark file!");
        exit(1);
    }

    printf("Enter the message to be embedded: ");
    scanf(" %[^\n]", message);

    output = fopen("output.bmp", "wb");
    if (output == NULL)
    {
        printf("Unable to create output file!");
        exit(1);
    }

    /* skip the header of the image file */
    fseek(image, 0L, SEEK_END);
    long int fileSize = ftell(image);
    fseek(image, 0L, SEEK_SET);
    int headerSize = fileSize - (512 * 512 * 3); // assuming header size is 54 bytes
    for (int i = 0; i < headerSize; i++)
    {
        getc(image);
    }

    /* copy header to output file */
    for (int i = 0; i < headerSize; i++)
    {
        putc(getc(image), output);
    }

    /* embed message and copy remaining data to output file */
    embedMessage(image, watermark, output, message);

    /* close files */
    fclose(image);
    fclose(watermark);
    fclose(output);

    /* extract watermark from output file and print message */
    output = fopen("output.bmp", "rb");
    if (output == NULL)
    {
        printf("Unable to open output file!");
        exit(1);
    }

    /* skip the header of the output file */
    fseek(output, 0L, SEEK_END);
    fileSize = ftell(output);
    fseek(output, 0L, SEEK_SET);
    headerSize = fileSize - (512 * 512 * 3); // assuming header size is 54 bytes
    for (int i = 0; i < headerSize; i++)
    {
        getc(output);
    }

    extractMessage(output);

    /* close files */
    fclose(output);

    printf("\n");
    return 0;
}

