int main(int argc, char *argv[]) {

    if (argc < 2) {
        printf("Error: Please enter a valid IP address and subnet mask!\n");
        return 0;
    }

    char *ip_addr = argv[1];
    char *subnet_mask = argv[2];

    struct in_addr addr;
    if (inet_pton(AF_INET, ip_addr, &addr) == 0) {
        printf("Error: Invalid IP address entered!\n");
        return 0;
    }

    int subnet_bits = 0;
    char *subnet_bit_ptr = subnet_mask;
    int octet_value = atoi(subnet_bit_ptr);

    if (octet_value < 0 || octet_value > 255) {
        printf("Error: Invalid subnet mask entered!\n");
        return 0;
    }

    // Convert subnet mask from dotted decimal to bits
    while (*subnet_bit_ptr != '\0') {
        if (*subnet_bit_ptr == '.') {
            if (octet_value < 0 || octet_value > 255) {
                printf("Error: Invalid subnet mask entered!\n");
                return 0;
            }
            subnet_bits += __builtin_popcount(octet_value);
            octet_value = 0;
        }
        else {
            if (*subnet_bit_ptr < '0' || *subnet_bit_ptr > '9') {
                printf("Error: Invalid subnet mask entered!\n");
                return 0;
            }
            octet_value = (octet_value * 10) + (*subnet_bit_ptr - '0');
        }
        subnet_bit_ptr++;
    }

    if (octet_value < 0 || octet_value > 255) {
        printf("Error: Invalid subnet mask entered!\n");
        return 0;
    }

    subnet_bits += __builtin_popcount(octet_value);

    long int num_hosts = (1 << (32 - subnet_bits)) - 2;
    unsigned int subnet_mask_int = ~(((1 << (32 - subnet_bits)) - 1));
    unsigned int network_address_int = ntohl(addr.s_addr) & subnet_mask_int;
    struct in_addr network_address;
    network_address.s_addr = htonl(network_address_int);

    printf("IP Address: %s\n", ip_addr);
    printf("Subnet Mask: %s\n", subnet_mask);
    printf("Network Address: %s\n", inet_ntoa(network_address));
    printf("Number of Hosts: %ld\n", num_hosts);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ROWS 100
#define MAX_NAME_LEN 20

// Structure to hold a record
typedef struct record {
    char name[MAX_NAME_LEN];
    int id;
} Record;

// Structure to hold a database index
typedef struct index {
    int id;
    Record records[MAX_ROWS];
} Index;

// Function to create a new index
Index* createIndex() {
    Index* index = (Index*)malloc(sizeof(Index));
    if (index == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for index\n");
        exit(1);
    }
    return index;
}

// Function to add a record to the index
void addRecord(Index* index, const char* name, int id) {
    Record* record = &index->records[index->id];
    strcpy(record->name, name);
    record->id = id;
    index->id++;
}

// Function to search for a record in the index
Record* findRecord(Index* index, const char* name) {
    int i;
    Record* record = NULL;
    for (i = 0; i < index->id; i++) {
        if (strcmp(index->records[i].name, name) == 0) {
            record = &index->records[i];
            break;
        }
    }
    return record;
}

// Function to display all records in the index
void displayRecords(Index* index) {
    int i;
    for (i = 0; i < index->id; i++) {
        printf("Record %d: %s\n", i + 1, index->records[i].name);
    }
}

// Function to free memory allocated for the index
void freeIndex(Index* index) {
    free(index);
}

// Main function
int main() {
    Index* index = createIndex();
    if (index == NULL) {
        return 1;
    }

    addRecord(index, "John Doe", 1);
    addRecord(index, "Jane Doe", 2);
    addRecord(index, "Bob Smith", 3);

    displayRecords(index);

    Record* record = findRecord(index, "Jane Doe");
    if (record!= NULL) {
        printf("Found record for Jane Doe\n");
    } else {
        printf("Record not found\n");
    }

    freeIndex(index);

    return 0;
}

