struct node {
    struct album data;
    struct node *next;
};

// function to add an album to the library
void add_album(struct node **head_ref, char title[], char artist[], int year, char genre[]) {
    struct node *new_node = (struct node *)malloc(sizeof(struct node));
    strcpy(new_node->data.title, title);
    strcpy(new_node->data.artist, artist);
    new_node->data.year = year;
    strcpy(new_node->data.genre, genre);
    new_node->next = (*head_ref);
    (*head_ref) = new_node;
    printf("\nAlbum added successfully.\n\n");
}

// function to display the library
void display_library(struct node *head) {
    if(head == NULL) {
        printf("\n\nThere are no albums in the library.\n\n");
        return;
    }
    printf("\n\n--- CURRENT LIBRARY ---\n\n");
    while(head != NULL) {
        printf("Title: %s\n", head->data.title);
        printf("Artist: %s\n", head->data.artist);
        printf("Year: %d\n", head->data.year);
        printf("Genre: %s\n\n", head->data.genre);
        head = head->next;
    }
}

// function to search for an album in the library
void search_album(struct node *head, char title[]) {
    while(head != NULL) {
        if(strcmp(head->data.title, title) == 0) {
            printf("\n\nTitle: %s\n", head->data.title);
            printf("Artist: %s\n", head->data.artist);
            printf("Year: %d\n", head->data.year);
            printf("Genre: %s\n\n", head->data.genre);
            return;
        }
        head = head->next;
    }
    printf("\n\nAlbum not found.\n\n");
}

// function to delete an album from the library
void delete_album(struct node **head_ref, char title[]) {
    struct node *temp = *head_ref, *prev;

    if(temp != NULL && strcmp(temp->data.title, title) == 0) {
        *head_ref = temp->next;
        free(temp);
        printf("\n\nAlbum deleted successfully.\n\n");
        return;
    }
    while(temp != NULL && strcmp(temp->data.title, title) != 0) {
        prev = temp;
        temp = temp->next;
    }
    if(temp == NULL) {
        printf("\n\nAlbum not found.\n\n");
        return;
    }
    prev->next = temp->next;
    free(temp);
    printf("\n\nAlbum deleted successfully.\n\n");
}

// function to generate a menu for the user to select from
int menu() {
    int choice = 0;
    printf("Welcome to the Music Library Management System!\n\n");
    printf("Please select from the following options:\n");
    printf("1. Add an album to the library\n");
    printf("2. Display the entire library\n");
    printf("3. Search for a specific album\n");
    printf("4. Delete an album from the library\n");
    printf("5. Exit the program\n\n");
    printf("Enter your choice (1-5): ");
    scanf("%d", &choice);
    return choice;
}

// main function
int main() {
    struct node *head = NULL;
    int choice;
    char title[50], artist[30], genre[20];
    int year;

    while(1) {
        choice = menu();
        switch(choice) {
            case 1:
                printf("\n\nEnter the following album details:\n");
                printf("Title: ");
                scanf(" %s", title);
                printf("Artist: ");
                scanf(" %s", artist);
                printf("Year: ");
                scanf("%d", &year);
                printf("Genre: ");
                scanf(" %s", genre);

                add_album(&head, title, artist, year, genre);
                break;

            case 2:
                display_library(head);
                break;

            case 3:
                printf("\n\nEnter the title of the album: ");
                scanf(" %s", title);
                search_album(head, title);
                break;

            case 4:
                printf("\n\nEnter the title of the album to delete: ");
                scanf(" %s", title);
                delete_album(&head, title);
                break;

            case 5:
                printf("\n\nExiting the program...\n\n");
                exit(0);
                break;

            default:
                printf("\n\nInvalid choice. Please enter a valid choice (1-5).\n\n");
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/in.h>

#define SMTP_PORT 25
#define BUFFER_SIZE 1024

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void send_smtp_command(int sockfd, const char *command) {
    if (send(sockfd, command, strlen(command), 0) < 0) {
        handle_error("Failed to send command");
    }
}

void receive_response(int sockfd) {
    char buffer[BUFFER_SIZE];
    int bytes_received = recv(sockfd, buffer, sizeof(buffer), 0);
    if (bytes_received < 0) {
        handle_error("Failed to receive response");
    }
    buffer[bytes_received] = '\0';
    printf("Server Response: %s", buffer);
}

void smtp_handshake(int sockfd) {
    receive_response(sockfd);
    send_smtp_command(sockfd, "HELO localhost\r\n");
    receive_response(sockfd);
}

void smtp_send_email(int sockfd, const char *from, const char *to, const char *subject, const char *body) {
    char command[BUFFER_SIZE];

    snprintf(command, sizeof(command), "MAIL FROM:<%s>\r\n", from);
    send_smtp_command(sockfd, command);
    receive_response(sockfd);

    snprintf(command, sizeof(command), "RCPT TO:<%s>\r\n", to);
    send_smtp_command(sockfd, command);
    receive_response(sockfd);

    send_smtp_command(sockfd, "DATA\r\n");
    receive_response(sockfd);

    snprintf(command, sizeof(command),
             "Subject: %s\r\nFrom: %s\r\nTo: %s\r\n\r\n%s\r\n.\r\n",
             subject, from, to, body);
    send_smtp_command(sockfd, command);
    receive_response(sockfd);

    send_smtp_command(sockfd, "QUIT\r\n");
    receive_response(sockfd);
}

int main() {
    const char *smtp_server = "smtp.example.com"; // Replace with your SMTP server
    const char *from_email = "you@example.com";   // Replace with sender's email
    const char *to_email = "recipient@example.com"; // Replace with recipient's email
    const char *email_subject = "Test SMTP Email";
    const char *email_body = "Hello, this is a test email from a simple SMTP client!";

    int sockfd;
    struct sockaddr_in server_addr;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        handle_error("Socket creation error");
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SMTP_PORT);

    // Convert IPv4 address from text to binary form
    if (inet_pton(AF_INET, smtp_server, &server_addr.sin_addr) <= 0) {
        handle_error("Invalid address or address not supported");
    }

    // Connect to SMTP server
    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        handle_error("Connection failed");
    }

    // Handshake with the SMTP server
    smtp_handshake(sockfd);

    // Send email through SMTP
    smtp_send_email(sockfd, from_email, to_email, email_subject, email_body);

    // Close socket
    close(sockfd);
    return 0;
}

