    return ((LineInfo *)b)->significance - ((LineInfo *)a)->significance; 
}

int calculate_significance(const char *line) {
    int score = 0;
    char *token = strtok(strdup(line), " ");
    while (token) {
        if (strlen(token) > 4) {
            score += 2; // Longer words hold more weight
        }
        if (strchr("aeiou", token[0]) != NULL) {
            score += 1; // Start with a vowel adds weight
        }
        token = strtok(NULL, " ");
    }
    return score;
}

void extract_meaning(char **text, int count) {
    LineInfo *lineInfos = malloc(sizeof(LineInfo) * count);
    int i;

    for (i = 0; i < count; i++) {
        lineInfos[i].line = text[i];
        lineInfos[i].significance = calculate_significance(text[i]);
    }

    qsort(lineInfos, count, sizeof(LineInfo), compare);

    printf("~~ Summarized Output ~~\n");
    for (i = 0; i < count && i < 5; i++) { 
        printf("%s\n", lineInfos[i].line);
    }
    free(lineInfos);
}

int main() {
    printf("** Text Summarizer by Cryptic Minds **\n");
    char *text[MAX_LINES];
    char line[MAX_LINE_LENGTH];
    int lineCount = 0;

    printf("Input your text (type 'END' to finish):\n");

    while (lineCount < MAX_LINES) {
        fgets(line, sizeof(line), stdin);
        if (strncmp(line, "END", 3) == 0) {
            break;
        }
        text[lineCount] = strdup(line);
        lineCount++;
    }

    extract_meaning(text, lineCount);

    for (int i = 0; i < lineCount; i++) {
        free(text[i]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_URL_LENGTH 2048

typedef struct {
    char *url;
    char *scheme;
    char *host;
    char *path;
    char *query;
    char *fragment;
} URLParts;

URLParts *sanitize_url(const char *url) {
    URLParts *parts = malloc(sizeof(URLParts));
    if (parts == NULL) {
        printf("Error: Failed to allocate memory for URLParts.\n");
        exit(1);
    }

    char *scheme_end = strstr(url, "://");
    if (scheme_end == NULL) {
        printf("Error: Invalid URL format.\n");
        free(parts);
        exit(1);
    }

    parts->url = strndup(url, MAX_URL_LENGTH);
    parts->scheme = strndup(url, scheme_end - url);
    parts->host = strndup(scheme_end + 3, strcspn(scheme_end + 3, "/?#"));
    parts->path = strndup(strchr(scheme_end + 3, '/'), strlen(scheme_end + 3) - strcspn(scheme_end + 3, "/?#"));
    parts->query = strndup(strchr(parts->path, '?'), strlen(parts->path) - strcspn(parts->path, "?#"));
    parts->fragment = strndup(strchr(parts->path, '#'), strlen(parts->path) - strcspn(parts->path, "?#"));

    return parts;
}

void print_url_parts(const URLParts *parts) {
    printf("URL: %s\n", parts->url);
    printf("Scheme: %s\n", parts->scheme);
    printf("Host: %s\n", parts->host);
    printf("Path: %s\n", parts->path);
    printf("Query: %s\n", parts->query);
    printf("Fragment: %s\n", parts->fragment);
}

void free_url_parts(URLParts *parts) {
    free(parts->url);
    free(parts->scheme);
    free(parts->host);
    free(parts->path);
    free(parts->query);
    free(parts->fragment);
    free(parts);
}

int main() {
    char input[MAX_URL_LENGTH];
    printf("Enter a URL to sanitize: ");
    fgets(input, MAX_URL_LENGTH, stdin);

    URLParts *parts = sanitize_url(input);
    if (parts == NULL) {
        return 1;
    }

    print_url_parts(parts);

    free_url_parts(parts);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_PIXEL_VALUE 255

/* Struct for an RGB pixel */
typedef struct {
    int r;
    int g;
    int b;
} PixelRGB;

/* Struct for an Image */
typedef struct {
    int width;
    int height;
    PixelRGB *pixels;
} Image;

/* Function to read an image from file */
Image *readImageFromFile(char *fileName) {
    FILE *file = fopen(fileName, "rb");
    if (!file) {
        fprintf(stderr, "Error: Could not open file %s\n", fileName);
        return NULL;
    }

    char magicNumber[3];
    int width, height, maxPixelValue;

    /* Read header information */
    fscanf(file, "%2s %d %d %d", magicNumber, &width, &height, &maxPixelValue);

    if (maxPixelValue > MAX_PIXEL_VALUE) {
        fprintf(stderr, "Error: Maximum pixel value is too large for this program\n");
        return NULL;
    }

    /* Skip over any comments in the file */
    char c = fgetc(file);
    while (c == '#') {
        while (c != '\n') {
            c = fgetc(file);
        }
        c = fgetc(file);
    }
    /* Return the file pointer to the previous character, which was not a '#' */
    fseek(file, -1, SEEK_CUR);

    /* Allocate memory for the image */
    Image *image = (Image *) malloc(sizeof(Image));
    if (!image) {
        fprintf(stderr, "Error: Could not allocate memory for image\n");
        return NULL;
    }
    image->width = width;
    image->height = height;
    image->pixels = (PixelRGB *) malloc(sizeof(PixelRGB) * width * height);
    if (!image->pixels) {
        fprintf(stderr, "Error: Could not allocate memory for image pixels\n");
        free(image);
        return NULL;
    }

    /* Read in the pixel values */
    int i, j;
    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            PixelRGB *p = &image->pixels[i * width + j];
            fscanf(file, "%d %d %d", &p->r, &p->g, &p->b);
        }
    }

    /* Close the file */
    fclose(file);

    return image;
}

/* Function to write an image to file */
void writeImageToFile(char *fileName, Image *image) {
    FILE *file = fopen(fileName, "wb");
    if (!file) {
        fprintf(stderr, "Error: Could not open file %s\n", fileName);
        return;
    }

    /* Write the header information */
    fprintf(file, "P3\n");
    fprintf(file, "%d %d\n", image->width, image->height);
    fprintf(file, "%d\n", MAX_PIXEL_VALUE);

    /* Write the pixel values */
    int i, j;
    for (i = 0; i < image->height; i++) {
        for (j = 0; j < image->width; j++) {
            PixelRGB *p = &image->pixels[i * image->width + j];
            fprintf(file, "%d %d %d\n", p->r, p->g, p->b);
        }
    }

    /* Close the file */
    fclose(file);
}

/* Function to flip an image horizontally */
void flipImageHorizontal(Image *image) {
    int i, j;
    for (i = 0; i < image->height; i++) {
        for (j = 0; j < image->width / 2; j++) {
            PixelRGB *p1 = &image->pixels[i * image->width + j];
            PixelRGB *p2 = &image->pixels[i * image->width + (image->width - j - 1)];
            /* Swap the pixel values */
            PixelRGB temp = *p1;
            *p1 = *p2;
            *p2 = temp;
        }
    }
}

/* Function to adjust the brightness of an image */
void adjustBrightness(Image *image, int amount) {
    int i, j;
    for (i = 0; i < image->height; i++) {
        for (j = 0; j < image->width; j++) {
            PixelRGB *p = &image->pixels[i * image->width + j];
            /* Adjust the brightness of each pixel by the specified amount */
            p->r = p->r + amount;
            p->g = p->g + amount;
            p->b = p->b + amount;
            /* Ensure that the pixel values do not fall outside the valid range */
            if (p->r < 0) {
                p->r = 0;
            } else if (p->r > MAX_PIXEL_VALUE) {
                p->r = MAX_PIXEL_VALUE;
            }
            if (p->g < 0) {
                p->g = 0;
            } else if (p->g > MAX_PIXEL_VALUE) {
                p->g = MAX_PIXEL_VALUE;
            }
            if (p->b < 0) {
                p->b = 0;
            } else if (p->b > MAX_PIXEL_VALUE) {
                p->b = MAX_PIXEL_VALUE;
            }
        }
    }
}

/* Function to adjust the contrast of an image */
void adjustContrast(Image *image, double amount) {
    int i, j;
    for (i = 0; i < image->height; i++) {
        for (j = 0; j < image->width; j++) {
            PixelRGB *p = &image->pixels[i * image->width + j];
            /* Adjust the contrast of each pixel by the specified amount */
            p->r = (int) ((p->r - MAX_PIXEL_VALUE / 2) * amount + MAX_PIXEL_VALUE / 2);
            p->g = (int) ((p->g - MAX_PIXEL_VALUE / 2) * amount + MAX_PIXEL_VALUE / 2);
            p->b = (int) ((p->b - MAX_PIXEL_VALUE / 2) * amount + MAX_PIXEL_VALUE / 2);
            /* Ensure that the pixel values do not fall outside the valid range */
            if (p->r < 0) {
                p->r = 0;
            } else if (p->r > MAX_PIXEL_VALUE) {
                p->r = MAX_PIXEL_VALUE;
            }
            if (p->g < 0) {
                p->g = 0;
            } else if (p->g > MAX_PIXEL_VALUE) {
                p->g = MAX_PIXEL_VALUE;
            }
            if (p->b < 0) {
                p->b = 0;
            } else if (p->b > MAX_PIXEL_VALUE) {
                p->b = MAX_PIXEL_VALUE;
            }
        }
    }
}

int main(void) {
    /* Read in the image from file */
    Image *image = readImageFromFile("example_image.ppm");
    if (!image) {
        return 1;
    }

    /* Flip the image horizontally */
    flipImageHorizontal(image);

    /* Adjust the brightness of the image */
    adjustBrightness(image, 20);

    /* Adjust the contrast of the image */
    adjustContrast(image, 1.5);

    /* Write the image to file */
    writeImageToFile("processed_image.ppm", image);

    /* Free the memory allocated for the image pixels and the image struct itself */
    free(image->pixels);
    free(image);

    return 0;
}

