        int output_fd = pipe_fd[0];
        char* data = "Hello, parent!";
        send_data(output_fd, data);
        free(data);
        wait(NULL);
        printf("Parent received data: %s\n", receive_data(output_fd));
        close(output_fd);
        return 0;
    }
