  if (argc != 3) {
    fprintf(stderr, "Usage: %s <dictionary file> <document file>\n", argv[0]);
    exit(EXIT_FAILURE);
  }

  // Load the dictionary
  load_dictionary(argv[1]);

  // Spell check the document
  spell_check(argv[2]);

  return 0;
}

