#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>
#include <signal.h>

#define MAX_TASKS 10
#define NAME_LENGTH 32

typedef struct {
    char name[NAME_LENGTH];
    int interval; // seconds
} Task;

typedef struct {
    Task tasks[MAX_TASKS];
    int task_count;
    pthread_mutex_t lock;
    int running;
} TaskScheduler;

TaskScheduler scheduler;

void initialize_scheduler() {
    scheduler.task_count = 0;
    pthread_mutex_init(&scheduler.lock, NULL);
    scheduler.running = 1;
}

void add_task(const char* name, int interval) {
    pthread_mutex_lock(&scheduler.lock);
    if (scheduler.task_count < MAX_TASKS) {
        strncpy(scheduler.tasks[scheduler.task_count].name, name, NAME_LENGTH);
        scheduler.tasks[scheduler.task_count].interval = interval;
        scheduler.task_count++;
        printf("Task '%s' added with interval %d seconds.\n", name, interval);
    } else {
        printf("Failed to add task: maximum task count reached.\n");
    }
    pthread_mutex_unlock(&scheduler.lock);
}

void remove_task(const char* name) {
    pthread_mutex_lock(&scheduler.lock);
    for (int i = 0; i < scheduler.task_count; i++) {
        if (strcmp(scheduler.tasks[i].name, name) == 0) {
            printf("Task '%s' removed.\n", name);
            for (int j = i; j < scheduler.task_count - 1; j++) {
                scheduler.tasks[j] = scheduler.tasks[j + 1];
            }
            scheduler.task_count--;
            break;
        }
    }
    pthread_mutex_unlock(&scheduler.lock);
}

void* execute_tasks(void* arg) {
    while (scheduler.running) {
        time_t now = time(NULL);

        pthread_mutex_lock(&scheduler.lock);
        for (int i = 0; i < scheduler.task_count; i++) {
            if (now % scheduler.tasks[i].interval == 0) {
                printf("Executing task '%s' at %s", scheduler.tasks[i].name, ctime(&now));
            }
        }
        pthread_mutex_unlock(&scheduler.lock);

        sleep(1);
    }
    return NULL;
}

void stop_scheduler(int sig) {
    scheduler.running = 0;
}

void cleanup() {
    pthread_mutex_destroy(&scheduler.lock);
}

int main() {
    signal(SIGINT, stop_scheduler);

    initialize_scheduler();

    pthread_t executor_thread;
    pthread_create(&executor_thread, NULL, execute_tasks, NULL);

    int choice;
    char name[NAME_LENGTH];
    int interval;

    while (1) {
        printf("\nTask Scheduler Menu:\n");
        printf("1. Add Task\n");
        printf("2. Remove Task\n");
        printf("3. Exit\n");
        printf("Choose an option: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter task name: ");
                scanf("%s", name);
                printf("Enter task interval (in seconds): ");
                scanf("%d", &interval);
                add_task(name, interval);
                break;
            case 2:
                printf("Enter task name to remove: ");
                scanf("%s", name);
                remove_task(name);
                break;
            case 3:
                scheduler.running = 0;
                pthread_join(executor_thread, NULL);
                cleanup();
                printf("Exiting...\n");
                return 0;
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h> // For sleep()
#include <time.h>

#define MAX_DEVICES 10
#define NAME_LENGTH 30

typedef struct {
    char name[NAME_LENGTH];
    int status; // 0 for OFF, 1 for ON
} Device;

Device devices[MAX_DEVICES];
int device_count = 0;

void add_device(const char *name) {
    if (device_count < MAX_DEVICES) {
        strncpy(devices[device_count].name, name, NAME_LENGTH);
        devices[device_count].status = 0; // Initially OFF
        device_count++;
        printf("Device '%s' added.\n", name);
    } else {
        printf("Maximum device limit reached.\n");
    }
}

void toggle_device(const char *name) {
    for (int i = 0; i < device_count; i++) {
        if (strcmp(devices[i].name, name) == 0) {
            devices[i].status = !devices[i].status;
            printf("Device '%s' is now %s.\n", devices[i].name, devices[i].status ? "ON" : "OFF");
            return;
        }
    }
    printf("Device '%s' not found.\n", name);
}

void status_report() {
    printf("\nSmart Home Device Status Report:\n");
    for (int i = 0; i < device_count; i++) {
        printf(" - %s: %s\n", devices[i].name, devices[i].status ? "ON" : "OFF");
    }
    printf("\n");
}

void schedule_device(const char *name, int seconds) {
    printf("Scheduling device '%s' to turn ON in %d seconds...\n", name, seconds);
    sleep(seconds);
    toggle_device(name);
}

void execute_command(const char *command) {
    char cmd[NAME_LENGTH];
    sscanf(command, "%s", cmd);

    if (strcmp(cmd, "ADD") == 0) {
        char name[NAME_LENGTH];
        sscanf(command + 4, "%s", name);
        add_device(name);
    } else if (strcmp(cmd, "TOGGLE") == 0) {
        char name[NAME_LENGTH];
        sscanf(command + 7, "%s", name);
        toggle_device(name);
    } else if (strcmp(cmd, "STATUS") == 0) {
        status_report();
    } else if (strcmp(cmd, "SCHEDULE") == 0) {
        char name[NAME_LENGTH];
        int seconds;
        sscanf(command + 9, "%s %d", name, &seconds);
        schedule_device(name, seconds);
    } else {
        printf("Unknown command: %s\n", command);
    }
}

void trim_newline(char *str) {
    size_t len = strlen(str);
    if (len > 0 && str[len - 1] == '\n') {
        str[len - 1] = '\0';
    }
}

int main() {
    char command[100];

    while (1) {
        printf("Enter command (ADD, TOGGLE, STATUS, SCHEDULE, EXIT): ");
        fgets(command, sizeof(command), stdin);
        trim_newline(command);

        if (strcmp(command, "EXIT") == 0) {
            printf("Exiting Smart Home Automation.\n");
            break;
        }

        execute_command(command);
    }

    return 0;
}

