  if (fp == NULL) {
    printf("Error: Could not access file!\n");
    exit(1);
  }

  while ((fgets(str, 1000, fp)) != NULL) {
    count++;
    charCount += strlen(str);

    for (i = 0; str[i] != '\0'; ++i) {
      //count words, vidCount, letters & lines in the file
      c = str[i];
      if (c == '\n') {
        lineCount++;
      }
      if (c == ' ' || c == '\t' || c == '\n') {
        if (flag == 1) {
          wordCount++;
          flag = 0;
        }
        if (letterCount > 0) {
          vidCount++;
        }
        letterCount = 0;
      }
      else {
        letterCount++;
        if (letterCount == 4 && (c == 'c' || c == 'C') && (str[i - 1] == ' ' || str[i - 1] == '\t' || str[i - 1] == '\n')) {
          vidCount++;
        }
        flag = 1;
      }
    }
  }
  fclose(fp);

